INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures of Pip', 'Play as the ultimate digital underdog in the Adventures of Pip,an action-platformer with a fresh gameplay twist inside a retro 32-bit world. Alas, Pip is an unlikely 1-pixel hero yet has the unique ability to absorb the pixels of his defeated enemies to evolve into three different forms. Players will skillfully switch between these three forms while exploring five worlds on an epic 10-hour campaign to defeat the Skeleton Queen. Adventures of Pip features a soundtrack by Jake “virt” Kaufman, composer for Shantae and the Pirates Curse, Bloodrayne: Betrayal, Shovel Knight, and more. The game will be available in June 2015 on Steam (PC/MAC), Nintendo WiiU, and coming soon to Xbox One, and PS4.' FROM games WHERE igdb_id = 14681 ON CONFLICT (game_id, language_code) DO NOTHING;
