INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '12 Labours of Hercules IV: Mother Nature', 'A time management/strategy game, in which you help Hercules (the ancient Greek mythical hero) and his team to progress through a set of levels to ultimate success. As a player, you direct the servants and heroes to remove obstacles, build structures and collect resources in order to fulfil the goal of each level and move on to the next level. The game has two modes: timed and relaxed. In timed mode, your goal is to beat the best time, which is a pretty hardcore experience. In relaxed mode, time is of no significance, and you just need to complete levels.' FROM games WHERE igdb_id = 26601 ON CONFLICT (game_id, language_code) DO NOTHING;
