INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ride Your Mind', 'Ride Your Mind is a BCI-VR-Game / NeuroVR Game that forces the user''s conscious to compete with his subconscious. The aim of RYM is to imbue the player with an awareness of his own brain as a consciously controllable tool comparable, for example, to his hand.' FROM games WHERE igdb_id = 141208 ON CONFLICT (game_id, language_code) DO NOTHING;
