INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartel Kings', 'Meet Max Muscles, Donnie Dollars and the rest of the Cartel Kings! They have really itchy trigger fingers, terrible dress sense and love stealing stuff. Guide them as they blast their way through the city, taking out the bad guys and blowing stuff up in the hunt for cash, treasure and even bigger guns! If you''re feeling lonely - or just want to show off - join a Cartel with friends and compete against enemy Cartels in the hunt for amazing rewards! Or visit Battle Bay and attack other players bases to steal their loot and upgrade your own millionaires mansion - solid gold toilets don''t buy themselves you know!
