INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '11gatsu no Arcadia', 'Ruiseitou is a solitary island in the southern sea far away from the main island. The beautiful ocean which surrounds the island and the charm of its historic Western-style streets draw in many visitors. In October, the streets are decorated in Halloween decorations in preparation for Kidai Gakuen’s founding festival. 
