INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asuria Awakens', 'In the remote Orlandrian coastal town of Casporur, home to the giant statues that rise out of the ocean called the Children of Asuria, something is amiss. The emissary from Orlandes City has been sending messages which are growing more and more alarming – they talk of tremors and civil unrest. When the emissary goes missing, it’s up to you to investigate the disappearance. A new darkness stalks the land. Is this the second coming of Asuria?' FROM games WHERE igdb_id = 175390 ON CONFLICT (game_id, language_code) DO NOTHING;
