INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rabbit Evolution Merge', 'I’ve got ears for days and big teeth, and I can bring you eggs but I’m not a bird. What am I? An ugly waiter? No, dummy, a rabbit! It might not be Easter, but it’s definitely bunny season for the addictive Evolution series, so get ready to drag, drop and dare, because your new favorite pet will be a hare!
