INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oberon', 'Oberon is a space exploration game in a multiplayer universe. You, the captain, will go through the process of acquiring a ship and putting together a crew to explore a fictional alternate dimension starting on a planet almost identical to Earth. The only real difference is that in 1968, in this alternate dimension, things went differently. The hippies took over the world and starting with policies of "no nukes" took the population down a much different path. 
