INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cluck Yegger in Escape from the Planet of the Poultroid', 'As space-faring free ranger, Cluck Yegger, you’ve been shot out of the sky by none other than your old arch nemesis, Colonel Zanderz. Your disabled ship is running on limited auxiliary solar power that charges during the daytime. But at night, confined to the cockpit, you must survive unwelcomed visits from a brood of peckish genetically modified poultroid looking for a late night snack. Can you survive seven nights to ESCAPE PLANET POULTROID?
