INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hanasaki Work Spring!', 'In the midst of spring, the season of first encounters and love, Yuuma was content to waste his time away. However, these dog days began to change with his chance meeting with the mysterious Inori, the Yuki-onna of Suzugaoka Gakuen. Soon after, he was invited by Ayano to the ‘ghost club’, which is actually not related to the occult, but rather a gathering place for people with regrets. He was made the new leader of the club despite his reluctance.
