INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mayan Death Robots', 'Duke it out with massive alien robots during the peak of the Mayan civilization. Nuke, zap, implode, incinerate and destroy your friends in singleplayer or local multiplayer. Win the adoration of your tiny Mayan tribesmen, and keep an eye out for Mayan Gods who will try to crash your party.' FROM games WHERE igdb_id = 13185 ON CONFLICT (game_id, language_code) DO NOTHING;
