INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circa Infinity', 'Circa Infinity is an arcade puzzle platformer filled with action. Reach the core of each level by slipping through a series of circular layers. Time your jumps carefully to avoid the creatures that reside within the circles and reach the next layer. As you go deeper, the action gets faster and more challenging! Can you keep up? The standard mode includes 50 stages of mind-bending action, with 5 bosses that will test your nerves. You can also measure your time yourself in speedrun mode.' FROM games WHERE igdb_id = 16312 ON CONFLICT (game_id, language_code) DO NOTHING;
