INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pilgrim', 'Pilgrim is an Wolf RPG Editor horror game by Kona Kona Kona Kona Kona (or Kona 5), and is part of The ''Verse with Itadori No Ko, Sukutte, and Akemi-Tan. It stars Akemi, a schoolgirl who dotes on her little sister Inago. At the school she goes to, an incident a month ago happened where three girls jumped off the top of the building and died- although it was classified as suicide, the girls showed no signs of being suicidal. While pondering this and walking with Inago one day, she comes across a little blonde girl calling herself Alice who tells Inago she will "fetch" her.' FROM games WHERE igdb_id = 85593 ON CONFLICT (game_id, language_code) DO NOTHING;
