INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pickomino', 175466, '2015-04-02', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pickomino', 'An appetizingly addictive dice game for up to 4 gambling gobblers. Barbecued worms are in high demand, and only the coolest-headed chicken can win the tasty snack! But beware: Anyone who doesn''t manage to grab a worm off the grill can help himself to those on his opponents'' plates! In Reiner Knizia’s popular dice game, 16 barbecue worm portions with different values are waiting on the grill to be snatched up by the dice-throwing chickens. The rules are simple, but don’t push your luck too far: To get your claws into one of the delicious worms, you roll all 8 dice at the same time. You then pick a value from your throw and remove all the dice showing the same value, before throwing the remaining dice again. If your score corresponds to an available barbecue worm portion on the grill you can take this portion - or maybe even grab a portion from the plate of your fellow players! You’ll need both the luck of the dice and the right strategy: Stick with your score, or roll the dice just one more time to get a better portion. The player with the most worms in his claws at the end of the game wins!' FROM games WHERE igdb_id = 175466 ON CONFLICT (game_id, language_code) DO NOTHING;
