INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mia Fey: Ace Spirit Attorney', 'Follow Mia Fey, the original Turnabout Lawyer, as she uncovers the secrets of DL-6. Murder after murder, incident after incident, Mia Fey is one step closer to the the truth about DL-6. But at the same time, she''s also getting herself into a cutthroat world of law, where all is not what it seems. In fact, the law system is broken. Prosecutors getting replaced every week, the prosecution department short on prosecutors... Utter chaos in the law. The ultimate question: will Mia Fey survive the world of law, and will she uncover the truth about DL-6? Or will she die trying?' FROM games WHERE igdb_id = 303005 ON CONFLICT (game_id, language_code) DO NOTHING;
