INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loot Heroes 2', 'They say heroes go to Valhalla to ever feast among the gods. Well, not all of them, apparently. You are the unlucky one, and will have to keep fighting in the other world as well. Play free online clicking game and struggle demonic creatures in an action-packed dungeon crawler. Select among dozens of heroes with their unique abilities and preferred weapons. Explore the isometric level map to hunt for chests and grab the loot. Recycle the finds you don’t need and upgrade the character’s strength, agility, vitality and intelligence. Achieve the main goal, and then replay the clicker with another hero. It’s like having 20+ free action games in one!' FROM games WHERE igdb_id = 101874 ON CONFLICT (game_id, language_code) DO NOTHING;
