INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancestory', 'Summon souls of tribesmen and cast devastating spells to vanquish your foes in a mix of turn-based strategy and card game. Featuring turn-based gameplay, multiple maps, underworldly minions and mighty spells, Ancestory gives the players an opportunity to lead their tribe into 1-on-1 battle on multiple different battlefields...all set on top of a massive golem! Players get to build their own decks before heading into battle to fight for control of totems spread across the battlefield. Players can find their foes through online matchmaking, inviting friends to play or honing their skills against an AI.' FROM games WHERE igdb_id = 13193 ON CONFLICT (game_id, language_code) DO NOTHING;
