INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fitz the Fox', 'Play as Fitz the Fox in this simplistic, retro style platformer. Help him through all the levels across seven different worlds to save his family from the hunter Willie and his gang. Designed to resemble a game for a classic portable game system with simple game play, pixelated graphics, and a 4-color color pallet. This callback to our childhood will test your skills, capture your imagination, and leave you satisfied when your quest is complete.' FROM games WHERE igdb_id = 12891 ON CONFLICT (game_id, language_code) DO NOTHING;
