INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Triple Triad', 'A mobile free-to-play game with hundreds of cards from across the entire Final Fantasy series. It featured rotating rule events and ranked matches against other players’ decks. Based on the Final Fantasy VIII trading card minigame. This was available to play in the Final Fantasy Portal App until it was removed in November 2024.' FROM games WHERE igdb_id = 386989 ON CONFLICT (game_id, language_code) DO NOTHING;
