INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Le Havre: The Inland Port', 'In the game Le Havre: The Inland Port, you and your opponent compete in order to amass the most wealth by building up the iconic French port of Le Havre. The game can be played locally against the computer, in hot-seat mode or online - competing against friends or global players in order to advance in the rankings. Drop in and out of play anytime and play an unlimited amount of games with your friends simultaneously, when you want, where you want.' FROM games WHERE igdb_id = 24027 ON CONFLICT (game_id, language_code) DO NOTHING;
