INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freaking Meatbags', 'Freaking Meatbags throws you into a futuristic world where robots have jobs, cephalopods aren''t confined to a single dimension, and humans pretty much just stand around talking to themselves. As a lowly cleaning robot, your task is to gather precious materials from each world before the solar system goes kaboom. As soon as you land, you realize this gig isn''t going to be as simple as you had hoped. During the day you''ll scramble to gather resources, build structures and keep your base in good repair. But when it gets dark, get ready to fight. Those rampaging wild robots aren''t here to have a knitting competition.
