INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare on Azathoth', 'Nightmare on Azathoth is a dark game, in which you might not want to find the truth. Manage your base, scavenge, collect memory fragments, and collect resources to power up your spaceship to escape this planet. Death only brings an endless time loop, that restarts everything on the 4th day. You know you have to escape this planet, and this endless time loop. Yet there is something itching your mind, something tells you you''ll have to do more than just escape...' FROM games WHERE igdb_id = 34130 ON CONFLICT (game_id, language_code) DO NOTHING;
