INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Morbius: The Utopia Conspiracy', 'The City of Frankfurt/M. is struck by a series of cruel murders. At the same time, Mike Morbius, private detective, gets assigned a new task about some suspicious project called "Utopia". Can Morbius find out what''s going on? Is there any link to the murders? Only Mike Morbius can find out. Currently, this game is available in German language only. Please keep in mind that this game heavily relies on text and speech. Knowledge of German language is mandatory! Loosely based on the characters and setting of the books "Meister des Feuers" and "Downtown" written by Johann C. Lotter. Permission to release this game was granted by the book author.' FROM games WHERE igdb_id = 90226 ON CONFLICT (game_id, language_code) DO NOTHING;
