INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatred', 'Hatred is an isometric shooter with disturbing atmosphere of mass killing, where player takes the role of a cold blood antagonist, who is full of hatred for humanity. It''s a horror, but here YOU are the villain. Wander the outskirts of New York State, seek for victims on seven free-roam levels. Fight against law enforcement and take a journey into the antagonist''s hateful mind. Gather equipment of the dead ‘human shields’ to spread Armageddon upon society. Destroy everything on your way of hunt and fight back when it''s disturbed...' FROM games WHERE igdb_id = 7857 ON CONFLICT (game_id, language_code) DO NOTHING;
