INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Witch Hunters: Full Moon Ceremony - Collector''s Edition', 'An old mirror reveals a terrible secret when a strange creature suddenly emerges and begins terrorizing your home. But you soon learn he''s just a lackey for an even bigger threat - a group of evil witches who want to take over the world! Stopping them won''t be easy, though. Your whole house has been enchanted with a series of deadly tricks and traps. A trip down the hallway is now a dangerous battle of will and wits. Can you overcome the obstacles and send the witches packing before the night is over? Find out in this thrilling Hidden Object Adventure game!' FROM games WHERE igdb_id = 74350 ON CONFLICT (game_id, language_code) DO NOTHING;
