INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Shuffle', 'Each stage in Pokémon Shuffle provides you a limited number of opportunities in which to move your Pokémon around. There is no time limit, so you can take as long as you like to study the board. To clear each stage, you''ll have to reduce the HP of the wild Pokémon you face to zero within a set number of moves. Use all the strategies and tactics available to you, and learn to read the board to spot future matches. Clearing Pokémon efficiently is the key to winning Pokémon Shuffle''s many stages!
