INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High Strangeness', 'High Strangeness is a hybrid of 8 and 16 bit games - a 12 bit adventure. The inspiration of the game comes from many Action-Adventure and RPG games of yesteryear. The game''s core ability is to switch between 8 and 16 bit worlds and the player uses their generational differences to solve puzzles and explore the universe. Throughout the game your pixel art perspective of the world will be infused with visions of watercolor illustrations that shed some light on your mysterious surroundings. The chiptune soundtrack by Dino Lionetti and Rich Vreeland backs up the aesthetic of the world and sets the mood for strange happenings.' FROM games WHERE igdb_id = 10093 ON CONFLICT (game_id, language_code) DO NOTHING;
