INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Humanity', 'The genre of the game is bullet hell without shoot''em up, it looks relatively low effort. It''s like b-movies, it''s so bad it''s good. The game design philosophy behind is controlled chaos, if you can''t control or learn from randomness, you might have a hard time mastering this very unique game. It also includes a handy map editor, a world explorer full of stuff created by our community, a fun fast paced multiplayer mode and lots of ships and cosmetics to unlock' FROM games WHERE igdb_id = 152015 ON CONFLICT (game_id, language_code) DO NOTHING;
