INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disgaea 5: Alliance of Vengeance', 'Disgaea 5: Alliance of Vengeance is a tactical role-playing video game. The evil demon emperor Void Dark devastates numerous Netherworlds after coming to power, with the help of an army of over one million soldiers known as The Lost. Following this, the Overlords of the Netherworlds under Void Dark''s rule attempt to rise up and take revenge. The game involves the player traveling across different Netherworlds in an attempt to bring the Overlords and heirs of each different world to join forces together to fight against Void Dark. The game will feature new systems not seen within prior titles in the Disgaea series. In addition, the number of characters displayable on-screen has increased to 100, compared to 10 characters on the earlier PlayStation 3 titles.' FROM games WHERE igdb_id = 11594 ON CONFLICT (game_id, language_code) DO NOTHING;
