INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotoGP 15', 'Are you ready for the new challenges ofMotoGP15? Compete against MotoGP, Moto2, and Moto3 riders on the 18 circuits of the 2015 championship in a bid to win the world champion title! MotoGP15is back with a range of new features to guarantee an even more comprehensive and compelling experience. The career mode has been expanded with the introduction of Personal Teams, the AI and physics have been overhauled and optimized with improved interaction between bike and rider, and a new game mode sees you trying to beat the times set by the best riders in each category.' FROM games WHERE igdb_id = 11275 ON CONFLICT (game_id, language_code) DO NOTHING;
