INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shutter', 'A female criminal Mrs. Rachel Solando has ran away from the Ashecliffe Hospital. Play a role of investigator US Marshal Teddy Daniels and you can also take a help from Chuck Aule. Travel to the Shutter Island where the Ashecliffe Hospital is situated where you both can carry on your investigation to discover information about the place. Shutter Island is a hidden object game which is made from the popular movie that has same title. You will experience scary environment in game that makes the game entertaining. Search out the hidden items, solve challenging puzzles and investigate evidence from different and unbelievable places of hospital.' FROM games WHERE igdb_id = 9404 ON CONFLICT (game_id, language_code) DO NOTHING;
