INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assault CorpsII', '"Assault Corps 2" (AssaultCorps, referred to as AC) is a full 3D multiplayer real-time strategy game.The game is a MOBA style Game and was developed by independent game studio(5 members). You can experience 18 kinds of distinctive combat units in the game，such as: combat robot、infantry fighting vehicle、tank、 self-propelled gun、helicopter、plane、gunship etc and 30+ distinctive ammo. You can develop more than 10 kinds of technology to enhance your combat units'' s ability. This game include 9 maps and 12 game modes to play. We''re working hard to add more units, more maps, more game modes. We hope you like this game, support us, for better game !' FROM games WHERE igdb_id = 35101 ON CONFLICT (game_id, language_code) DO NOTHING;
