INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare of the Snow', 'On a very snowy and dark morning, Yuuki Shinozaki, a shy middle schooler, was preparing for her trip to a farewell party of her school...but an unfortunate tragedy happened. When Yuuki was helping her friend, Taiga, to look for his lost handphone, she was taken mysteriously to a lost, dark dimension where a big, mysterious mansion existed. Yuuki didn''t know...that this is all just the beginning of her NIGHTMAREs in THE SNOWy and freezing night...' FROM games WHERE igdb_id = 150559 ON CONFLICT (game_id, language_code) DO NOTHING;
