INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disorder', 'You may think it''s simple enough to run and jump your way through life. But there''s more to this world... or, rather, these worlds. You''re entering the duality of a distressed mind, controlling light and dark versions of the same environment. You hold the key to switching from one to the other. Every step forward shows a new obstacle, and a new way to alter it between dark and light. Become comfortable in both worlds and you may be able to make sense of the dreamy landscape around you. You may even find an explanation for why you''re here.' FROM games WHERE igdb_id = 17827 ON CONFLICT (game_id, language_code) DO NOTHING;
