INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black & White Bushido', 'Things are rarely ever black and white, but that’s not the case in Black & White Bushido. With an original soundtrack and gorgeous, stylistic 2D visuals, you’re either a light or shadow samurai facing down your opponents in a combat arena. The black and white style makes each battlefield a dangerous place, filled with hiding spots for four players to fight and hide in. It’s a simple concept boiled down to an infinitely replayable set of team death match or Capture the Flag sessions. 
