INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yuki Koi Melt', 'It’s been only three months since Miharu moved to the snowy town of Yubane, where he was greeted with first true taste of winter. Since he’s sensitive to cold, he greatly hates winter and patiently waits for spring like a hibernating bear. However, he was unfortunately targeted by the school’s top weirdo Usagi. She wanted him to join the mysterious ‘Winter Club’. It was a club to enjoy and love winter.
