INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman: Arkham Underworld', '"Batman: Arkham Underworld" is an iOS and Android game developed by Turbine, Inc. and released on iOS on July 14, 2016. Set a few years before the events of Arkham Asylum, the game gives players control over a team of villains—including infamous Batman enemies such as the Riddler, Harley Quinn, Mr. Freeze, Killer Croc, Scarecrow, and Bane—and has them build hideouts and recruit henchmen, with the goal of becoming Gotham City''s "next criminal kingpin". Arkham Underworld features voice acting, with many actors reprising their roles from the main installments in the series. The game was shut down in 2017.' FROM games WHERE igdb_id = 54606 ON CONFLICT (game_id, language_code) DO NOTHING;
