INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barren Roads', 'Nuclear weapons have the left the world barren and scorched the earth. Survival has never been harder for mankind. Resources are scarce as life has left this world. You are forced to constantly move and scavenge the next area for resources. Rivers are dry. Many of wanderers never survived the icy nights as the moon crosses the sky. Roam a massive streaming map featuring ruined highways and cities. Survive and outwit other survivors, like yourself. Scavenge, loot, and explore during the day and find shelter during the freezing nights. Beware of the beasts and unknown as the sun sets.' FROM games WHERE igdb_id = 35954 ON CONFLICT (game_id, language_code) DO NOTHING;
