INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Pirate Dernshous', 'Dernshous was basically what I liked from Escape Velocity, which was seeing little spaceships flying around and shooting and docking at space stations, and the idea of going aboard other ships. So that''s pretty much what Dernshous is, but I feel like it''s still too much of a conventional game that it doesn''t work how I''d like. I think I would''ve preferred it narrowed down more with a stronger focus rather than being half a normal space game.
