INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Ninjago: Shadow of Ronin', 'There is a new threat in Ninjago, and he goes by the name of Ronin. With help from his army of dark samurai, Ronin steals the Ninjas'' memories using an ancient weapon called the Obsidian Glaive. In LEGO Ninjago: Shadow of Ronin, it is up to players to help the Ninjas regain their memories and reclaim their powers before Ronin completes his plan and releases an even greater evil on Ninjago.' FROM games WHERE igdb_id = 19006 ON CONFLICT (game_id, language_code) DO NOTHING;
