INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yukti', 'Yukti is a puzzle game in which you play with the tactics, creativity and imagination of your touch. All levels have a simple goal to land the asteroid onto the sun. You draw a stroke that travels in space with the speed and the path that you define. Your stroke repeats its pattern in space and travel to dodge the black holes in the space. Sun is surround by a shield that protects it from any other outer body, but if traveling asteroid absorbs the energy of other planets, it can penetrate the shield to enter the surface of sun. The game starts with easier puzzles that teach you to understand the tactics that you need to solve the puzzles.' FROM games WHERE igdb_id = 174360 ON CONFLICT (game_id, language_code) DO NOTHING;
