INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Exam', 'Final Exam takes place in the near future after an AI revolution has led to the establishment of a new sort of government. You are seeking a job within this government: your performance in the “final exam” determines the outcome. You wake up on the day of your exam to find that your world has unexpectedly changed. You leave your room to seek answers, and find the Administration Centre deserted... 
