INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phineas and Ferb: New Inventions', 'There is no time to get bored on holidays! Half-brothers Phineas and Ferb always know how to entertain themselves. They can build an entertainment park in their backyard or think up something very special… But their elder sister Candace is not very happy of their tricks. She is always ready to bust the brothers and tell their mother on them. And Phineas has a pet platypus called Perry who has a secret of his own. He just pretends to be a silly amenable pet but in fact lives a double life as a secret agent codenamed P battling the malicious scientist Dr. Doofenshmirtz… On the whole, they all have a lot to worry about!
