INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Soccer', 'World of Soccer is a free-to-play multiplayer online soccer game. Unlike other similar soccer games, the user controls a single player instead of an entire team. You can join different teams and play against other teams. Improve yourself and your teamplay and compete on many tournaments to be the best in the game!' FROM games WHERE igdb_id = 137970 ON CONFLICT (game_id, language_code) DO NOTHING;
