INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ama no Sora Retrospect', 'Amanosora is a small town of around 60,000 people, formed ten years ago from the merger of the villages of Tensei and Sorami. Shikimi attends the local school with the cleaning club leader Himari and his lively kouhai Shinon. There’s a rumour at the school that the door to another world would be opened by pressing a certain sequence of buttons in the elevator at the lighthouse in the Stargazing Commemorative Hall.
