INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golden Axe: The Curse of Death Adder', 'Death Adder is a sequel to the fourth part of Golden Ax. This is a work made by fans.Very good scenarios and great news in this game. Extremely tactical variety is possessed by the characters who are available for use. They have different characteristics and the game with each of them is different.New pictures and new landscapes are added, and a character from other sagas you take part in your campaigns.
