INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plush', 'Plush combines stuffed animal simulation with the imagination of a little girl to provide a unique puzzle experience. To successfully complete each level, the player must arrange the stuffed animals in such a way as to make them all "happy" before bedtime. Each stuffed animal has it''s own preferences (and physics), so this is easier said than done. Despite the relaxing atmosphere, make no mistake, ''Easy'' difficulty is enjoyable for kids and casual gamers, ''Normal'' and ''Hard'' are a challenge that any puzzle gamer can appreciate.' FROM games WHERE igdb_id = 24629 ON CONFLICT (game_id, language_code) DO NOTHING;
