INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lowglow', 'Lowglow - an audiovisual puzzle journey. The game includes over 100 mind-bending levels. The gameplay is physics driven and plays with different gravitations, pushes, pulls and portals for starters. You are an astral light drop in the endless sea of darkness, trying to bring shine where it''s needed the most. Each set of levels has a strong theme where the coloring, audio and mechanics vary greatly. The levels have lots of weird mechanics that are sure to keep you entertained throughout the game.' FROM games WHERE igdb_id = 18190 ON CONFLICT (game_id, language_code) DO NOTHING;
