INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Phantasm Dream', '龙皇社东方同人作品第一作LH01-东方幻梦笺！ 本次引起异变的是神秘“可怖”的鬼怪力量—整个幻想乡笼罩着噩梦下，究竟幻想乡的少女们会如何行动呢？ 三组自机飒爽登场，更有蕾米莉亚芙兰朵露两姐妹参与事件当中！不同的自机会有不同的操作体验，望能给您带来丰富的操作体验！' FROM games WHERE igdb_id = 123848 ON CONFLICT (game_id, language_code) DO NOTHING;
