INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feist', 'Feist is a beautiful, poetic and action packed game, with an enchanting and spooky atmosphere. It tells the story of a small creature surviving in a mysterious, hostile world. Once players escape the crude crate the strange, lumbering beasts used for a trap, players journey through sprawling forests, mountains, caves, and swamps, brought to life in a cinematic physical-effects style reminiscent of Jim Henson’s The Dark Crystal, or Hedgehog in the Fog.
