INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The White Canvas', 'The White Canvas is the story of Nico Sales, a very ironic painter without inspiration and with a lot of personal problems. Midas, the most important patron in the world has arrived at his city. Nico needs to find him and convince him to take care of his artistic career. This won''t be very easy for Nico because feels depressed and anxious due to his lack of inspiration. Moreover, Midas it''s very evasive and discret. Will Nico be able to find Midas and convince him? Try to help him and you will find out a lot of interesting things about the charismatic painter Nico Sales. -- Thanks to David Silva for his help.' FROM games WHERE igdb_id = 306131 ON CONFLICT (game_id, language_code) DO NOTHING;
