INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hibachi Hero', 'Slice, cut and chop your way to victory! Hibachi Hero is a fast-paced first person food shooter. Stay on your toes to survive the dinner rush and become the ultimate hibachi chef. Fling your knife to cut steaks, peppers, fish, and more as they fall from above. Keep a close eye on the foods falling - don''t cut the bad foods! Build to the highest multiplier you can to get your score soaring. Watch out, five strikes and it''s game over! Try out the lottery system to unlock new knives and restaurant locations. Will you become the next Hibachi Hero?' FROM games WHERE igdb_id = 395015 ON CONFLICT (game_id, language_code) DO NOTHING;
