INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Public Transport SImulator', 'Jump behind the steering wheel in this driving simulator. There are three different types of missions, depending on what type of vehicle you choose. Choose one of many buses to transport passengers around the city. Jump in as a taxi driver and give a lift to clients waving their hands around the city. Choosing a race car, opens up Checkpoint racing tracks in the city. For each customer serviced or race finished, you get experience points, which unlock additional vehicles and locations. For each vehicle there are unlockable upgrades and paint jobs. Upgrades and paint jobs are unlocked simply by earning experience with that vehicle. Drive carefully! When you crash, passengers fall and you lose experience.' FROM games WHERE igdb_id = 383133 ON CONFLICT (game_id, language_code) DO NOTHING;
