INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moero Crystal', 'Moero Crystal is a role-playing video game developed by Compile Heart for the PlayStation Vita. It is part of the Genkai Tokki series and the sequel to Moe Chronicle. The player will need to make a team of five monster girls for battle. The protagonist Zenox can’t attack, but he’ll help provide support with power ups. The new "Insert" command also lets you move ahead one of the characters in the attacking order. Upon defeating a monster girl, you’ll get to recruit them through its touchscreen "scratching" feature. There are also some items that will allow you to get them to join you later without having to do the scratch feature. They will allow you to instead give them a scratch later on your own time.' FROM games WHERE igdb_id = 11494 ON CONFLICT (game_id, language_code) DO NOTHING;
