INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demong Hunter', 'Demong Hunter is the story of a Hunter trying to Regain Peace by defeating the bug ‘Demong’created by the whole brain in the virtual world. Enjoy the Battle with Different Special Skills and Unique Attack Style for each Character. Enjoy Fantasy RPG elements by Collecting Gold to increase your Stats And Defeating the Boss to Collect Artifacts for Special Effects. After the Ending, Many Volume Stages will lead you to the True Ending. Highly Recommend this game to those who Love Fast-Paced Battles with Adorable Characters, and those who Love Continuous Stages with Various Attack Actions with a Sword and a Bow.' FROM games WHERE igdb_id = 146745 ON CONFLICT (game_id, language_code) DO NOTHING;
