INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'KindergarTen 1: No Mercy', 'The game takes place at a kindergarten, where the player is a cleaner who discover things, which is helping in the investigation. During the day, the kindergarten is open, so every morning the children are coming, and you must clean up the whole place. The kindergarten closes at 9:00 PM which means you have to be there at 8:50 PM. The game contains 5 nights of cleaning which pay you a reward of 26$ each day. Every night while cleaning, you find more and more information, that could help you solve the mystery of the murder.
