INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('urizen-shadows-of-the-cold', 34574, '2015-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co46ke.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vdkjufbtog4ckvmddgrq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urizen Shadows of the Cold', 'KEYBOARD AND JOYSTICK COMPATIBILE. Grab a copy now for $1.99 before it updates to the Deluxe Version priced at $3.99. Stretch across lands of unforeseeable cold, and trouble in Urizen Shadows of the Cold. Now a massive 50 warrior "head bopping", sword slashing platformer with characters raging from giants, ninjas, knights, aliens, sorcerers, mermaids and demons. It includes 34+ massively created stages with more to come. It also includes a cool cheat menu, an enabled combo system, an implemented save feature, enabled music test menu, crazy and intense retro styled game play paying tribute to that old plumber and that ninja with the dragon tooth sword, and unique weapons/projectiles for each warrior enabling close counter melee attacks. Also featuring some cool cutscenes and a unique but weird storyline. It also handles many secrets, hidden warriors and hidden gems. Deluxe Frosty Edition Update will be coming 3rd quarter 2017. Update will include Steam Achievements.' FROM games WHERE igdb_id = 34574 ON CONFLICT (game_id, language_code) DO NOTHING;
