INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball: Xenoverse', 'Dragon Ball Xenoverse is the first installment of the Xenoverse series and the Dragon Ball game developed by Dimps. It is the first fighting game to feature full 3D battles similar to the Budokai Tenkaichi series. Fighters can traverse the levels free-roaming in large spaces and can fight on ground, in the air and underwater. The game features spoken dialogue from a majority of main characters while in battle, and characters show facial expressions when they strike an opponent or take damage. Although limited, the players have some freedom to explore the planet Earth as it exists in the Dragon Ball universe along with a handful of other locations.' FROM games WHERE igdb_id = 7408 ON CONFLICT (game_id, language_code) DO NOTHING;
