INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('maquisard', 128427, '2015-05-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wru.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2e1x.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maquisard', 'Maquisard is a charming game of snooping and investigation. As the lobby boy at a fancy hotel, the player receives clues from the resistance about the identity of a government agent and tries to figure out their identity by snooping on the guests over the course of three days. Players must listen in on conversations, peek into rooms, and observe the guests'' habits in order to figure out which guests has all the traits of their target. Maquisard is a single-player puzzle game that has an unique non-linear investigation gameplay and draws on the visual aesthetics of Wes Anderson''s film The Grand Budapest Hotel.' FROM games WHERE igdb_id = 128427 ON CONFLICT (game_id, language_code) DO NOTHING;
