INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Risk', 'Modern combat meets Risk - the classic game of global domination. Risk steps into the near future with modern armies. Using the 2010 rules as standard, Risk offers an exciting strategic experience. Direct the war from your high-tech control room, fighting on the classic map layout on 3D; Deploy tanks, planes and infantry… All in the modern warfare twist on the classic game of global domination!' FROM games WHERE igdb_id = 82434 ON CONFLICT (game_id, language_code) DO NOTHING;
