INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Zestiria', 'Tales of Zestiria is a Japanese role-playing game. It is the fifteenth main entry in the Tales series. As with previous entries in the Tales series, the game uses a variation of the action-based Linear Motion Battle System, with additional elements including a navigable open world, and the ability for certain characters to fuse into a single entity in battle to deliver powerful attacks. The story follows Sorey, a young man blessed with powers by a mystical spirit race known as the Seraphim who act as a stabilizing force in the land, as he travels to free the land of Glenwood from the threat of the Hellion, creatures spawned by negative emotions.' FROM games WHERE igdb_id = 6452 ON CONFLICT (game_id, language_code) DO NOTHING;
