INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bionite: Origins', 'Bionite: Origins is an Action-Strategy game based on hover tank warfare, set on various planets and moons throughout the solar system. Action-Strategy games are also called "hybrids" because they combine the FPS and RTS elements into the most engaging gaming experience available for the PC. Bionite: Origins integrates the key FPS and RTS elements into one seamless battle experience. Action-Strategy games are the most engaging games to play; because they require strategy to win, AND are fun to play because they include the First Person Shooter experience.
