INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities XXL', 'Design, build, and manage the world''s largest and most diverse cities in Cities XXL, a sandbox RTS simulator. Bigger and better than ever before with a more powerful game engine and new interface, become the mayor of your very own sprawling metropolis. With town-planning including home locations, retail plots, offices, industry and infrastructure across 47 architectural styles and over 1000 buildings, manage the happiness of your city''s denizens, with leisure activities, landmarks, and ecology and pollution management. With new structures, but also all-new ecological buildings and upgrades, such as the park-and-ride, electric car dealership, and bike hire, Cities XXL offers a greener approach!' FROM games WHERE igdb_id = 10094 ON CONFLICT (game_id, language_code) DO NOTHING;
