INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'God Eater 2: Rage Burst', 'God Eater 2 Rage Burst is an enhanced version of God Eater 2, adding new features and elements to the game. A new chapter titled "Rage Burst" is added to the story, featuring content separated into six difficulty levels within the main quests. Rage Burst introduces a new game mechanism known as "Blood Rage", which involves filling an Awakening Gauge by attacking enemies, and then making a pledge to the God Arc once it activates, granting various buffs to the player.
