INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom & Destiny Advanced', 'Venture with the most nerdy anti-heroes of all times, face a crazy adventure, defeat a mad business man and save the universe, one fetch quest at a time. Embody 13+ different heroic spirits, equip gear, master skills and character combinations to fight in turn based combat 300+ different enemies and, while you progress into an over 30 hours main quest, feel free to explore 500+ locations looking for more than 100 hidden secrets. The action doesn’t stop with the single player adventure! Enter the Online Arena and fight other players in asynchronous battles! Fight and unlock 100 unique multiplayer perks, 64+ costumes and more and reach the top online leaderboard!' FROM games WHERE igdb_id = 25944 ON CONFLICT (game_id, language_code) DO NOTHING;
