INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubot', 'At first sight, Cubot is a puzzle-game with a minimalist gameplay, just move color cubes towards tiles of the same color. It''s really easy, but it will be a torture for your mind to complete all levels of the game because the apparent simplicity of the game is in contradiction with the complexity of the level-design. Moreover, an important point in the gameplay is if you have multiple cubes, they move simultaneously !' FROM games WHERE igdb_id = 36000 ON CONFLICT (game_id, language_code) DO NOTHING;
