INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Child of Light: Ultimate Edition', 'Own the Child of Light: Ultimate Edition with the full game plus seven add-on content packs. Encounter eccentric creatures, from wicked witches to evil sea serpents, and discover the vast land of Lemuria. Fight alongside your allies to upgrade your stats, unlock unique abilities, and use unique gems to improve your skills. Work together with your allies to solve puzzles and search for mysteries. Experience a story carefully crafted in verse and rhyme with an original soundtrack.
