INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 4: Dancing All Night - Nanako to Odoro Issho ni Pose!', 'Persona 4: Dancing All Night: Nanako to Odoro Issho ni Pose! is a promotional game for Persona 4: Dancing All Night where you dance with Nanako by correctly guessing which pose she does at the end of her dance. The correct answers are selected randomly and change for each playthrough, and the player is awarded a P4D themed wallpaper if they complete all three stages.
