INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fireman Sam to the Rescue', 'Fireman Sam and friends are back to save the day in a brand new adventure! Help Sam and the Pontypandy fire crew in three action-packed missions; Brave to the core: Fire-fighter emergency, Rescue at Sea and Animal Rescue. Sam and the team are always on duty in this interactive story packed with fun puzzles and games!' FROM games WHERE igdb_id = 85640 ON CONFLICT (game_id, language_code) DO NOTHING;
