INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'An Imp? A Fiend!', 'Stuck in the Underworld without the slightest clue why, a young fiend has a bit of a mystery to solve in this action/adventure platformer. With a world to explore, a past to uncover, and quite the task to complete, players must embark on a quest filled with monsters, towns, dungeons, bosses, and various platforming challenges.' FROM games WHERE igdb_id = 35635 ON CONFLICT (game_id, language_code) DO NOTHING;
