INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead or Alive 5: Last Round', 'Dead or Alive 5 Last Round is a fighting game developed. It is the third updated version of the 2012 game Dead or Alive 5, following the 2013 games Dead or Alive 5 Plus and Dead or Alive 5 Ultimate. Dead or Alive 5 Last Round features all the content from Dead or Alive 5 Ultimate, adding new costumes and customizable hairstyles, as well as two new characters and two new stages. The PlayStation 4 and Xbox One versions received upgraded graphics, running at 1080p resolution and 60 frames per second. These two version also use the new game engine called Soft Engine and designed to better depict "softness" of characters'' bodies.' FROM games WHERE igdb_id = 8211 ON CONFLICT (game_id, language_code) DO NOTHING;
