INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galak-Z: The Dimensional', '"Galak-Z is a modern, A.I. and physics-driven open-world action game, viewed through the lens of the classic 16-bit space shooter. It’s 2D combat taken to the next level. Players will take control of a variety of classic spacecraft inspired by anime of the late 70’s and early 80’s, piloted by a cast of characters every bit as colorful as the rainbow-hued explosions erupting all around them. Newtonian physics take center stage as players experience finely-tuned control, blasting enemies, unleashing missile salvos, and tossing enemies into explosive obstacles.
