INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Keep Talking and Nobody Explodes', 'One player is trapped in a virtual room with a ticking time bomb they must defuse. The other players are the “Experts” who must give the instructions to defuse the bomb by deciphering the information found in the bomb defusal manual. But there’s a catch: the experts can’t see the bomb, so everyone will need to talk it out – fast!' FROM games WHERE igdb_id = 13226 ON CONFLICT (game_id, language_code) DO NOTHING;
