INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoiyo Mori no Hime', 'When her village was burned by the militarized country of Stahl, Ilza escaped into a dark forest and ends up lost. People believe that the forest, "Yoiyo Mori", is cursed, and those who take a step inside will never come out again. As she wanders inside the forest, Ilza loses consciousness and is taken into a certain mansion—where she finds seven men who bear resentment towards Stahl. They are waiting for a chance to take revenge on the country, and her life with them has just begun…' FROM games WHERE igdb_id = 293326 ON CONFLICT (game_id, language_code) DO NOTHING;
