INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyro', 'Kyro is a top-down puzzle game inspired by the Adventures of Lolo series of games, which were enjoyed on the original Nintendo Entertainment System. Each level takes place on a single game screen, and you must get to the yellow doorman to continue to the next level. Note the signs; they hold words of truth and wisdom. They''re also Chatty Cathys, so you could just ignore them if you wanted. 
