INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Souls II: Scholar of the First Sin', 'Dark Souls II: Scholar of the First Sin is an enhanced edition of Dark Souls II, released in April 2015 by FromSoftware and Bandai Namco Entertainment. This version includes updated graphics, improved performance, and all previously released DLC expansions (Crown of the Sunken King, Crown of the Old Iron King, and Crown of the Ivory King). It also features rebalanced gameplay, new enemy placements, additional NPCs, and expanded lore,' FROM games WHERE igdb_id = 8222 ON CONFLICT (game_id, language_code) DO NOTHING;
