INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlastZone 2', 'BlastZone 2 is an action packed side scrolling shooter that will really get your adrenaline pumping! Play solo or join up with a friend locally or online and battle the alien forces that have invaded the planet and take the fight to them! Feel the excitement of breaking through the enemy barricade at high speed! Enjoy innovative gameplay mechianics such as 2nd person shooter sequences and creative use of 3D gameplay mechanics added to the traditional 2D formula. There are also tons of game modes, ship types, difficulty levels, and turbo modes to keep you entertained for a very long time. There are litterally hundreds of ways to play the game, so every player can have their own unique experience! Explore the many multiplayer strategies such as the heavy gunner and light defender to buy time while the ultimate weapons charge up!' FROM games WHERE igdb_id = 35756 ON CONFLICT (game_id, language_code) DO NOTHING;
