INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nobunaga''s Ambition: Tenshouki with Power-Up Kit HD Version', 'The 6th release of the "Nobunaga''s Ambition" historical simulation game series has been reborn at the STEAM store as "Tenshouki with Power-up Kit HD Version." Players become the rulers of their clans and aim to unify the country under their leadership. Players will enjoy all the distinctive NA game elements, including a learning system, battle system, and an army system.' FROM games WHERE igdb_id = 90610 ON CONFLICT (game_id, language_code) DO NOTHING;
