INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Bionicle: Mask of Creation', 'Mask of Creation is a melee combat game based on the 2015 characters and story of LEGO BIONICLE''s second generation. Several characters are playable, including all six Masters, also called the Toa, and Ekimu, the Mask Maker. The Toa must search for their Golden Masks of Power, fighting Skull Spiders and Skull Warriors along the way. Each character has their own campaign through their own elemental region, and at the end of each campaign, the Lord of Skull Spiders is battled. Different pieces of are collected throughout the journey, allowing each character''s appearance to be customized.' FROM games WHERE igdb_id = 343361 ON CONFLICT (game_id, language_code) DO NOTHING;
