INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey of a Special Average Balloon', 'Journey of a Special Average Balloon is an Arcade type Adventure game. Journey as a balloon across many worlds to save the rainbow! Collect coins to reveal rainbow shards, dodge enemies with difficult maneuvers, and collect bonus chests if you can! Compete or cooperate with a friend in several different multiplayer modes! Two people can compete by playing Survival and seeing who can last longer, or by playing Spike Chaser and trying to destroy/evade the other. There is also a small Co-Op adventure for two friends to play cooperatively! Go for the high-score in Slingshot Galley, a timed mode in which you control a slingshot and try to pop as many balloons as you can before time runs out! There are also many challenges and bonuses to unlock!' FROM games WHERE igdb_id = 19616 ON CONFLICT (game_id, language_code) DO NOTHING;
