INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pool Nation FX', 'Pool Nation FX, is a seriously fun Pool & Snooker Sim! A visually stunning billiards simulation with the critically acclaimed POOL NATION physics engine. Play 8 Ball, 9 Ball, Snooker, Killer & more, unlimited Career modes with customised difficulty levels, Trickshots, Local and Online Multiplayer and spectate.' FROM games WHERE igdb_id = 17645 ON CONFLICT (game_id, language_code) DO NOTHING;
