INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fahrenheit: Indigo Prophecy Remastered', 'Originally released in 2005, Fahrenheit (known as Indigo Prophecy in North America) was a breakthrough in interactive narrative, teetering between the worlds of cinema and gaming while also embracing them, carving its own unique genre in the entertainment landscape. This newly remastered edition features updated graphics, controller support AND is based on the uncut/uncensored international version of the game.
