INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return Null: Episode 2', 'Episode 2 begins a few hours after the ending of Episode 1. Jack Drebin wakes up in the headquarters of the Dissonant Octave and discovers their plans to fight against the oppression of the Local Security Force. He joins the supposed terrorist group in their plot to undermine the rule of the LSF. In a final effort to exact revenge, Jack agrees to take part in one more mission to overthrow the oppressive forces that govern his world. And in joining the rebellion, he uncovers terrible truths which point to the exciting climax to be revealed in Episode 3.' FROM games WHERE igdb_id = 24726 ON CONFLICT (game_id, language_code) DO NOTHING;
