INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tormenta: O Desafio dos Deuses', 'Accept the challenge! Gatzvalith, the Lord of the Storm, has kidnapped the powerful mage Niala and intends to sacrifice her in an unholy ritual. His goal: to spread the Storm across Arton, engulfing the continent in the Crimson Tempest. It is already too late to stop the ritual. But two heroes lost in the history of the world may still arrive in time! The Challenge of the Gods is a computer game set in the universe of Storm. Play as Samson, a human barbarian/rogue, or Sellena, an elf mage/cleric, and explore great moments in the history of Arton, such as the battle of Fort Amarid, the fall of Lenórienn and the march of the Kishin of Master Arsenal!' FROM games WHERE igdb_id = 344204 ON CONFLICT (game_id, language_code) DO NOTHING;
