INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koko kara Natsu no Innocence!', 'Not so long ago, as the urban areas progressed in their development towards being an information society, there were many places in the mountainous area which kept the same olden feeling. Yoshitsugu was a visitor from 100 years in the future who came to the mountain village Akio-mura. He had been labelled as a failure in the ultra-competitive society in the future, so it was unknown how he was able to travel to the past, an opportunity open only to those with high social positions.
