INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exist Archive: The Other Side of the Sky', 'The game is set within modern day Tokyo, Japan, alongside a world on another planet, called “Protolexa.” There are a dozen young protagonists, all of whom are evil, soul-collecting gods who have become embroiled in the issues of all gods. The main focus of the game is dungeon crawling. You’ll be able to explore dungeons from a side-view perspective, while the characters are presented in a 3D, chibi-sized style. The characters can use various skills like jumping, dashing, and more to solve puzzles. The enemies are not randomized, they are presented on screen prior to battle.' FROM games WHERE igdb_id = 11540 ON CONFLICT (game_id, language_code) DO NOTHING;
