INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Prism', 'The Prism is a 2D puzzle platformer about two pixels, 02 and 03 lost inside a vast prison. Unlike a normal prison, this one is alive. It is called the Prism. Its eyes stare from a distance and watch its prisoners carefully, analyzing their actions and breathing down their necks. You will face many challenges but you don''t have to do it alone. You can play by yourself or locally with a friend.' FROM games WHERE igdb_id = 34506 ON CONFLICT (game_id, language_code) DO NOTHING;
