INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man 256', 'Pac-Man 256 is a 2015 Android and iOS video game in the Pac-Man series. It is inspired by the glitched 256th level of Pac-Man. In the game, the player must continuously navigate an endless maze while avoiding ghosts and using power-ups and power pellets to combat them. Fruits grant a temporary multiplier, and as Pac-Man eats dots, it is up to the player to try to top their high score.
