INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('not-without-my-donuts', 35338, '2015-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa23d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zkucf6ucnlup2dantstr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Not without my donuts', 'You both stand ready to be champions. Your vows to protect your world and every remaining donut have toughened your resolve to overcome all obstacles. In the icing that sits on top of your flavored cupcake you some how understand how importantly the need to survive has become, as you glance at the donut you now defend, you realize, ‘Breakfast never tasted so delicious.’
