INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Three Fourths Home: Extended Edition', 'In her mid-20''s, Kelly has been forced to move back to Nebraska. Back to that flat expanse, that seemingly endless sea of rustling cornstalks peppered by rusty silos and rustier towns. A typically intense Midwestern storm is approaching while Kelly is out; she needs to get home.
