INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stasis', 'Stasis is a point-and-click, sci-fi, horror adventure game played from a unique isometric perspective. Stasis intertwines a gruesome narrative with retro adventure gameplay. Combine items, interact with computers and solve puzzles while experiencing the gritty atmosphere.
