INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarCraft II: Legacy of the Void', 'You are Hierarch Artanis, leader of the mighty protoss race. Years ago, your homeworld of Aiur fell to the merciless zerg Swarm. Now, at long last, you have raised a powerful fleet of warships known as the Golden Armada, and are poised to reclaim your world. But an ancient evil—Amon—threatens this destiny and the fate of the entire galaxy. Only you can reunite the protoss factions and defeat the coming darkness before it consumes all life in the sector.' FROM games WHERE igdb_id = 458 ON CONFLICT (game_id, language_code) DO NOTHING;
