INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astral Terra', 'Astral Terra is a fantasy-themed sandbox world-crafting game for PC with RPG and survival elements. Set in a beautiful smooth voxel world that’s generated on the fly and completely editable, no two players will have the same experience, as everything from the skills you learn to the world you play in is fully unique and customizable. Explore the endless realm of the Fae Sanctum as a Planar Warden and pick out a piece of land to build your fortress via your unlimited power to terraform and build. Gather resources for crafting and building or just explore the various biomes for the sake of discovery. From character progression with abilities and powers, to the terrains and the environments, everything is procedural and editable.' FROM games WHERE igdb_id = 16882 ON CONFLICT (game_id, language_code) DO NOTHING;
