INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SCI-Hard', 'You wake from an accident into a new world with new challenges, new threats, and some guy with a huge head. It''s a strange world. One filled with senile grandparents, animals with shrunken green heads, and looming ominous music. You must build your strength, stay fit, defend your stuff, and investigate the strange happenings in the small town of Unnamed, USA. With more than 30 different scenarios and mini-games, a full cast of odd characters to talk with, and dozens of collectible items and weapons only you can save the town from impending doom. SCI-Hard puts you, the player, in the chair of someone with a Spinal Cord Injury. Introducing you to new challenges and obstacles all while trying to save the world from legions of mutated animals.' FROM games WHERE igdb_id = 368255 ON CONFLICT (game_id, language_code) DO NOTHING;
