INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fish World', 'Create your own underwater paradise in Fish World, a fun-filled 3D aquarium simulation game whereby you can collect from a huge variety of beautiful fishes, including both realistic and fantastical ones, design amazing tanks and share them with your friends! Let your creativity shine in Fish World today!' FROM games WHERE igdb_id = 337220 ON CONFLICT (game_id, language_code) DO NOTHING;
