INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HuniePop', 'HuniePop is a 2015 adult dating sim/match-3 puzzle game published and developed by HuniePot. Funding for the game was raised via Kickstarter. It is available in two versions, one censored and one uncensored, although the censored one can easily be patched. The game follows a player (can be male/female) trying to woo a variety of women by going on dates with them, giving them gifts and talking to them.' FROM games WHERE igdb_id = 9655 ON CONFLICT (game_id, language_code) DO NOTHING;
