INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sature', 'Live the experience of being a painter. Drawing from the process of mixing colors on a palette, Sature offers an engrossing turn-based strategy game. Each turn, players place colored tiles on the board. These tiles mix with neighboring colors to create new tactical situations and opportunities for inventive play. The result is a chess-like dance where players rely on their wits to outmaneuver their opponent. When the board is complete and a game is finished, a unique palette emerges from the way the colors have mixed as they were played on the board.' FROM games WHERE igdb_id = 165295 ON CONFLICT (game_id, language_code) DO NOTHING;
