INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bucket Knight River Adventures', 'Become the bucket knight as you raft down the river, avoiding all the hazards coming your way. Collect coins to unlock upgrades, or buy equipment so that you can go even farther! The river will become more and more hazardous, and move faster and faster, so you are going to need all the upgrades you can get. Compete with players all around the world, and see who can get the highest score. Challenge yourself by trying to complete all the achievements, with tricky challenges and milestones to keep you busy!' FROM games WHERE igdb_id = 114608 ON CONFLICT (game_id, language_code) DO NOTHING;
