INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survarium', 'Survarium is a post apocalyptic Free to play FPS game, currently in steam early access. In its current state, Survarium offers three playable competitive gamemodes in a FPS style. With interesting map design, character progression and balanced pay to win methods, Survarium is proving to be a hit. The Survarium development team is also releasing an open world gamemode which just like Dayz, requires players to scavenge, loot and survive. This gamemode is currently in development, and not yet released. No release date has been issued.' FROM games WHERE igdb_id = 2976 ON CONFLICT (game_id, language_code) DO NOTHING;
