INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pure x Connect', 'Hayato has yearned for a heart-throbbing romance for a long time, but instead is bored wasting away time every day. He wishes to fall in love like in an eroge, but everyone around him just makes fun of him for it. But that’s what every guy wants, right? Is it really so wrong to want such a relationship?
