INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unmechanical: Extended Edition', 'Unmechanical: Extended is an award-winning platformer/puzzle game loved by countless players around the world, now coming to Xbox One with a brand new “Extended” story episode that contains even more puzzles and mysteries to solve. Do you dare enter? Our story starts when you are abducted into a secret underground world full of fantastic machinery. Flying freely through the strange world, you have to solve a wide variety of puzzles and mysteries. The journey to freedom begins! On your adventure you may also begin to understand the reason behind it all - the underworld may be more than it seems, the fateful descent more than just chance, and you might not be entirely alone there after all…' FROM games WHERE igdb_id = 20310 ON CONFLICT (game_id, language_code) DO NOTHING;
