INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil''s Bluff', 'The 11 vs 1 online murder mystery that offers a ground-breaking take on the Survival Horror genre. Enter the Crawley Mansion for the annual Halloween scavenger hunt atop the infamous Devil’s Bluff. Mystery, deception, betrayal, and mayhem are the order of the day. Let the hunt begin!' FROM games WHERE igdb_id = 34941 ON CONFLICT (game_id, language_code) DO NOTHING;
