INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('volvox', 18551, '2015-12-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/u74d9lhp9ptcwjeevkkk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bs0o67sk2cezviwffxh6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Volvox', 'Volvox is a puzzle game based on a triangular grid. The characters, called Trimoebas, are triangular unicellular organisms undertaking the building of the first pluricellular beings, traveling through the evolution and the 250 levels of the game. The Trimoebas bear functional properties on their sides, such glue, explosive, insulating and hooks, but they are useful only if the Trimoeba is correctly rotated: you will have to prepare the right path and make the Trimoebas overstep each other to bring them in the right position with the right phase. Developed and published by Neotenia.' FROM games WHERE igdb_id = 18551 ON CONFLICT (game_id, language_code) DO NOTHING;
