INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curse of Mermos', 'Curse of Mermos is a free, lighthearted hack and slash game with fast paced action and challenging combat. Players wield the Hammer of Horus or shoot the Crossbow of Neith to defeat hordes of monsters in the tomb of Ebo. The game features unlock-able abilities and skill upgrades for personalized combat. Special game modifiers allow players to customize each play-through.' FROM games WHERE igdb_id = 35678 ON CONFLICT (game_id, language_code) DO NOTHING;
