INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stickman Volleyball', 'Stickman Volleyball, the most played fun sports game comes right to your device. Experience pure beach volleyball fun with fast paced gameplay, an astonishing atmosphere, stunning smooth animations, simple controls, insane action and tons of replay value. Choose your favorite team and rank up while playing various seasons or cups in spectacular locations like roof tops and beaches or simple dominate in a quick game or space volleyball. You have full control over your player with manual running, passing and smashing. Choose your favorite volleyball team from more than 36 different skilled teams and lead them to glory in more than 25 locations. 
