INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Chibi Knight', 'The Kingdom of Oukoku is threatened by the spicy influence of General Tso. Citizens have placed their hope in a small knight who fits the requirements of ancient legends. Which path will the Chibi Knight choose... the path to the mysterious Island of Mahou to learn spells from its sorcerers or the path to the Beastmaster mountains to summon and ride an array of ferocious animals? Your choice will determine Oukoku''s fate!' FROM games WHERE igdb_id = 36438 ON CONFLICT (game_id, language_code) DO NOTHING;
