INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tompi Jones', 'Tompi Jones is a fun platform game in 2.5d inspired in classic platform games. You can play across six worlds between jungles, forests, medieval villages, Aztec pyramids, castles and cemeteries. You must avoid the traps and defeat your enemies with projectile weapons, fighting with the sword or with special items. You will plan with your propeller hat or fly with your jetpack. You must find all the secret pieces and collect coins scattered throughout the levels in order to improve your skills.' FROM games WHERE igdb_id = 35236 ON CONFLICT (game_id, language_code) DO NOTHING;
