INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skyhill', 'Skyhill is a roguelike story about staying alive when there is no reason to. You are a resident of Skyhill hotel,who survived biological catastrophe. Goal - is to get out of your penthouse in search of other people and salvation. But all elevators in the building are off and floors are flooded with hazards. You are not sure is there any other survivors, as far as you know everyone in the building died, or… changed beyond recognition. Those who provided room service and pushed buttons in elevators for you not so long ago… well now all they want is to rip off your flesh to get to your tasty insides… So much for customer service. You face the dilemma: on the one hand you have to get out from the damn building, on the other hand your hotel suite is your only “Fort” that protects from the horrors of post-apocalyptic reality.' FROM games WHERE igdb_id = 11562 ON CONFLICT (game_id, language_code) DO NOTHING;
