INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloop', 'Bloop is an action adventure game where you play as a young, subterranean-dwelling slime on a quest to discover the surface world. Slime your way through dungeons, battle bandits, and uncover a secret that threatens all of Slimedom. The fate of the cavernous realm rests on your, um...shoulders! 
