INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dyscourse', 'Dyscourse is an interactive choice-based narrative adventure game where you journey through a stylized world of choice and consequence. You play as Rita, an unfortunate art school grad turned barista, who is now stuck on a desert island with a crew of oddball travelers after a plane crash. That last choice you just made? It may end up being integral to your group’s survival, or it may lead you down a path to murder and cannibalism.
