INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard West: Collector''s Edition', 'Hard West takes place in a heavily fictionalized version of the American Old West following standards of the Western genre but with the addition of supernatural elements, taking inspirations from XCOM: Enemy Unknown. Themes typical of the Western genre, such as bank robberies, lynching and the gold rush are commonplace in the game''s world but also metaphysical beings such as Death and the Devil directly influence the lives of the local population. Creatures such as demons, ghosts and undead gunslingers are present in the game''s vision of the old west.' FROM games WHERE igdb_id = 51822 ON CONFLICT (game_id, language_code) DO NOTHING;
