INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psycho-Pass: Mandatory Happiness', 'In a world where psychological states can be quantified, every choice has consequences, victims can become criminals, and the very nature of truth can warp and shift. Can detectives Nadeshiko Kugatachi and Takuma Tsurugi remain on the path of justice as they face the ugly truths of humanity?' FROM games WHERE igdb_id = 23849 ON CONFLICT (game_id, language_code) DO NOTHING;
