INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream', 'Dream’s gameplay is strongly based around exploration with games such as Yume Nikki and LSD being the initial inspiration for the concept. On top of this we have been inspired by the narrative elements in Dear Esther and Deus Ex’s non-linear story telling and environments, the resulting gameplay maintains aspects of all 4 games. There will be many puzzles to solve, horror sections and some more narrative focused areas. So we hope it will have a range of elements for everyone to enjoy.' FROM games WHERE igdb_id = 3104 ON CONFLICT (game_id, language_code) DO NOTHING;
