INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Unstoppables', 'What a catastrophe! The four friends Mai, Jan, Achim and Melissa were standing in front of the food stand completely unsuspectingly when, suddenly, their beloved guide dog Tofu was kidnapped by a mysterious villain! The four friends know their mission clearly: they must free Tofu from the hands of his kidnapper. The friends won’t let their differences get in their way. Only through great teamwork will they be able to overcome the various obstacles in the way of their goal. They are «The Unstoppables!»
