INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labyrinthine Dreams', 'Labyrinthine Dreams is a short puzzle game about Beth, a young woman who is standing at Death’s Door. After a traumatic childhood and a tough entry into the world of adulthood, she was just starting to take control of her life. However, she is now up against an insidious enemy who threatens to take everything away from her. During what may be her final hours, Beth wanders through important moments in her life while also staying a few steps ahead of the monster who won’t rest until she is no more.
