INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Predestination', 'Predestination is a turn-based sci-fi 4X game set in the distant past of our own galaxy. Ships from countless races are sent back in time by an enemy known as the Revenants and must now work to rebuild their empires. Explore the galaxy, colonise habitable worlds, meet alien races, and wage war. Predestination aims to blend the gameplay of classic titles like Master of Orion II with more modern 3D graphics and new game mechanics 4X fans have been waiting years to get their hands on, such as a 3D galaxy map, tactical fleet combat, advanced planetary exploration, terraforming, a 3D ship designer, and many other features.' FROM games WHERE igdb_id = 35997 ON CONFLICT (game_id, language_code) DO NOTHING;
