INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities: Skylines', 'Cities: Skylines is a modern take on the classic city simulation genre. The game introduces new game play elements to realize the thrill and hardships of creating and maintaining a real city whilst expanding on some well-established tropes of the city building experience. From the makers of the Cities in Motion franchise, the game boasts a fully realized transport system. It also includes the ability to mod the game to suit your play style as a fine counter balance to the layered and challenging simulation. You''re only limited by your imagination, so take control and reach for the sky!' FROM games WHERE igdb_id = 9066 ON CONFLICT (game_id, language_code) DO NOTHING;
