INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Ghost', 'Gravity Ghost is a peaceful gravity hopper: Run, jump, and orbit your way through a handpainted galaxy. Join Iona the ghost as she searches for her lost best friend, the ghost fox. Explore a shattered galaxy and rescue its survivors, armed with powerups and mysterious terraforming powers. Meet the 7 magical guardians and best their challenges. There''s no killing, no dying, no way to fail. Just hours of blissing out to buttery-smooth gravity goodness.' FROM games WHERE igdb_id = 16669 ON CONFLICT (game_id, language_code) DO NOTHING;
