INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '123 Slaughter Me Street', 'Welcome everyone to 123 Slaughter Me Street! A criminal on the run, you find yourself evading police as you make your escape down an alley. You see an old fire escape and scramble up to the roof of an abandoned building; you are safe here. As the patrol cars drive past, you slip into the shadows.' FROM games WHERE igdb_id = 19810 ON CONFLICT (game_id, language_code) DO NOTHING;
