INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drive to Hell', 'Drive to Hell is an action-packed shooter where you''ll take a ride through an army of monsters to exact revenge on the Demon King for destroying your favorite dive bar. Enemies assault from all sides, each with its own special personality and attack style. To take them down, you''ll have access to many weapons and items as well as unique vehicles, special abilities and more!' FROM games WHERE igdb_id = 36135 ON CONFLICT (game_id, language_code) DO NOTHING;
