INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curse of the Crescent Isle DX', 'A curse has befallen the Crescent Isle and it''s up to you to save it. Luckily the curse has transformed your people into helpful monsters such as drills, blobs, icicles, and gravity flipping...things. With your monster subjects in hand you''ll have to drill through rocks, maneuver through spiky terrain, freeze water to pass over the sea, and restore your kingdom to its former glory.' FROM games WHERE igdb_id = 35398 ON CONFLICT (game_id, language_code) DO NOTHING;
