INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('irotoridori-no-sekai-worlds-end-rebirth', 61144, '2015-03-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vqe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsjsb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Irotoridori no Sekai: World''s End Rebirth', 'When he was a child, Yuuma received a special power from the “translucent magician”, Shinku. Just by touching someone with his hand, he is able to cure all of their wounds in return for some of his memories. In the furthestmost port town of Kazatsugahama, there is a link to a another world hidden in the basement of the Arashiyama-sou dormitory. Within this world he lives his life like a dream. One night while the full moon shone brightly, a girl descended from the sky. “Mister magician, please save me.”' FROM games WHERE igdb_id = 61144 ON CONFLICT (game_id, language_code) DO NOTHING;
