INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Almightree: The Last Dreamer', 'Take on the role of the last dreamer imbued with the ability to commune with nature on a magical level. Use the power of “plantsportation” to teleport blocks of dirt to create new paths to the seedlings and give your life force to the dying world around you so that new roots can take hold and keep the land together. It is time to wake up dreamer for it is up to you to quickly traverse what is left of the world your people let die.' FROM games WHERE igdb_id = 24031 ON CONFLICT (game_id, language_code) DO NOTHING;
