INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Mixed Martial Arts 3', 'Step into the world of MMA in World of Mixed Martial Arts 3. In this simulation title, you control every aspect of the MMA world. Take control of an MMA company and run it the way you want. Decide who to hire, what matches will take place, and who doesn''t make the cut! Train fighters, negotiate contracts, watch matches unfold in real time with detailed commentary, and much, much more! Can you make it to the top of the industry?' FROM games WHERE igdb_id = 35885 ON CONFLICT (game_id, language_code) DO NOTHING;
