INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Logomancer', 'Ardus Sheridan and his apprentice John Marrow are negotiators for the dream commodities company Powell-Mercer and have been sent to the seaside city of Ordolus in order to finalize a contract with the region''s most recently discovered logomancer, Glenton Dahl. The story begins as the duo reaches the city limits. What is the nature of the dreamworld that everyone is connected to? What is the true nature of logomancy? Is the emotion felt for a fictional character different from the emotion felt for a real person? Did the ancient peoples of Callosum like slow-roasted brisket?' FROM games WHERE igdb_id = 35129 ON CONFLICT (game_id, language_code) DO NOTHING;
