INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runbow', 'Runbow is an action party game with a unique art style and a never-before seen colour mechanic that will keep you running back for more. Platforms and obstacles appear and disappear as the background colour changes, so if you can’t see something, it doesn’t exist. Whether you''re playing alone or with friends, Runbow is fast, frantic, and a lot of fun.
