INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrath of Athena', 'Wrath of Athena is set in ancient Greece, where heroes of mythology and mankind coexist. When the forces of Hades rise and bring terror to Athens, only you can stand against them. Begin your journey from Athens to the Underworld, exploring iconic landmarks like Mount Olympus and the River Styx. Face endless dungeons filled with monsters and treasures, uncover powerful weapons and artifacts, and recruit followers to aid you in battle.' FROM games WHERE igdb_id = 368399 ON CONFLICT (game_id, language_code) DO NOTHING;
