INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarDrive 2', 'StarDrive 2 is a 4X Turn Based Strategy game built in the classic style of the singular and incredible Master of Orion 2. In StarDrive 2 you will explore a vibrant galaxy filled with danger and intrigue in a deep turn-based strategy layer. You will design custom spaceships and deploy them into real-time battles with spectacular graphics and effects. You will conquer worlds in a turn-based tactical ground combat mode. You''ll deal with aliens, pirates, monsters, and ancient threats, most of whom want to kill you to make room for their own empires.
