INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'God Eater Resurrection', 'God Eater Resurrection is an action roleplaying game and a remake of the 2010 game Gods Eater Burst, which in turn was an enhanced version of the original God Eater game. The game features further balancing and new gameplay elements. All elements from God Eater 2 and God Eater 2 Rage Burst are featured, and an all new "Predator Style" has been added. It also adds another story that tie the stories of God Eater Burst and God Eater 2.' FROM games WHERE igdb_id = 11858 ON CONFLICT (game_id, language_code) DO NOTHING;
