INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Never Ending Night', 'Never Ending Night is a 2D side-scrolling exploration game. As the Player, you roam through a mysterious world you have no recollection of. Traverse through a broken world and survive through the mechanical monstrosities that have managed to survive the calamity... But don''t worry, cue in MLBY, a strange mechanical butterfly sidekick, and you''ll be ready to illuminate your way past beauty, perils, and adventure. By interacting with objects and the environment you can overcome your enemies as you figure out the mysteries of both you and MLBY. Lanterns will mark your progress through the eerie darkness.' FROM games WHERE igdb_id = 35919 ON CONFLICT (game_id, language_code) DO NOTHING;
