INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt Rally', 'Dirt Rally is a racing video game focused on rallying. Players compete in timed stage events on tarmac and off-road terrain in varying weather conditions. On release, the game features 17 cars, 36 stages from three real world locations, and asynchronous multiplayer. Rallycross and player versus player multiplayer modes are planned. Codemasters announced a partnership with the FIA World Rallycross Championship in July 2015. The early access version contains cars from the 1960''s, 70''s, 80''s, Group B, Group A, 2010s Modern Rally, and Pikes Peak.' FROM games WHERE igdb_id = 9928 ON CONFLICT (game_id, language_code) DO NOTHING;
