INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prominence', 'After living for generations as persecuted refugees, the Letarri people set their sights on a far-off planet as a promising new home. But when the interstellar mission to colonize the new world goes terribly awry, the fate of their people falls into the hands of a lone adventurer. Now it''s up to you to unravel the mystery of what happened. Can you save them and their mission, or is it already too late?
