INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diadra Empty', 'Diadra Empty is a free-roaming shoot-''em-up on a grand scale. Take the role of Nyalra and her faithful dragon Minimi in a fantastical quest to save her missing sister, and battle legions of monsters and menacing bosses. The touching storyline is complemented by the game''s beautiful 2D visuals, particle effects and environments rife with enemies, and glowing projectiles. Diadra Empty gives you extreme speed and maneuverability, huge environments in which to seize the upper hand, and plenty of firepower and upgrades. You always have options, and the immensely detailed on-screen radar will help you keep track of even the off-screen chaos.' FROM games WHERE igdb_id = 17133 ON CONFLICT (game_id, language_code) DO NOTHING;
