INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenoblade Chronicles X', 'Xenoblade Chronicles X is an action role-playing video game and a part of the Xeno series of video games, serving as a spiritual successor to Xenoblade Chronicles on the Wii. In a similar fashion to the original, the game plays as an open world role-playing video game, with an emphasis on exploration. Traveling can take place on foot, or in large humanoid robots, approximately four times the height of the average playable character, called "Skells" ("Dolls" in the Japanese version), that the player may opt to control. The Skells have the ability to fly, traverse water, and transform into vehicles such as motorcycles or tanks. Aerial battles will also take place in the game.' FROM games WHERE igdb_id = 2366 ON CONFLICT (game_id, language_code) DO NOTHING;
