INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eden Star', 'Have you ever wanted to make a fresh start on an alien world? Eden Star is a survival game that drops you onto the alien landscape of Pharus 7, free to explore and gather resources, but you’ll want to be careful: death is permanent. You need to use resources to construct defences, craft weapons and build up outposts to protect your vital Eden Kit. With physics-based combat, free-form construction and destructible environments to explore.' FROM games WHERE igdb_id = 14377 ON CONFLICT (game_id, language_code) DO NOTHING;
