INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hotline Miami 2: Wrong Number', 'Hotline Miami 2: Wrong Number is the brutal conclusion to the Hotline Miami saga, set against a backdrop of escalating violence and retribution over spilled blood in the original game. Follow the paths of several distinct factions – each with their own questionable methods and uncertain motivations – as unforeseen consequences intersect and reality once again slips back into a brilliant haze of neon and bloodshed.' FROM games WHERE igdb_id = 2126 ON CONFLICT (game_id, language_code) DO NOTHING;
