INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hegemony III: Clash of the Ancients', 'Centuries before Caesar, Alexander and Philip, the forested hills and rocky coasts of ancient Italy draw cultures from across the Mediterranean with promises of wealth and prosperity. Bronze-clad hoplites from the powerful Greek city-states set sail across the Adriatic to carve out bridgeheads of Hellenic culture amongst the native Italic hill tribes, while aggressive bands of Gallic skirmishers make the trek South across the Alps in search of fertile new land. And along the marshy banks of the Tiber river, a small upstart city called Rome battles for independence from the ruling Etruscan confederacy.
