INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coffin Dodgers', 'Coffin Dodgers sees you take on the role of saving one of seven quirky retirement village residents, each racing for their soul in "pimped up" mobility scooters against none other than the Grim Reaper himself. Our old heroes are armed with a variety of homemade weapons and gadgets to take on anything the Grim Reaper and his Zombie army may throw at them. Can you survive the retirement village?
