INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crypt of the Serpent King', 'Crypt of the Serpent King is a medieval first-person hack''n''slash dungeon crawler with roguelike elements. Explore large, randomly generated dungeons. Fight goblins, orcs, skeletons, giant spiders and all sorts of underworld creatures using melee and ranged weapons. Jump over lava pits and spike traps. Level up your character''s abilities and choose between 3 levels of difficulty, from casual to hardcore.' FROM games WHERE igdb_id = 31307 ON CONFLICT (game_id, language_code) DO NOTHING;
