INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Crawlers HD', 'Dungeon Crawlers is a game designed to explore the fun and funny concept of what "Ghostbusters" might''ve looked like if it were set in a dungeon. It''s a turn-based strategy game that is easily accessible. Don''t expect to dive too deep into statistics and weapons types here. The interface is highly streamlined. This game is all about launching and playing, but still being demanding and challenging to even the most seasoned of turn-based vets.' FROM games WHERE igdb_id = 35642 ON CONFLICT (game_id, language_code) DO NOTHING;
