INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Last First Kiss', 'The Story: Even after all these years, you haven’t forgotten about your first love. You try confessing your feelings to him, but he turns you down. Luckily the friends you grew up with are there to help mend your broken heart… until that night, when you become more than just friends… Characters: Ayato Hidaka "The Likeable Popular Guy" Ichiya Misono "The Unfriendly Lone Wolf" Makoto Morimachi "The Loyal Older Brother" Takamune Kitami "The Passive Soccer Player" Riku Morimachi "The Quiet Younger Brother" Contents: Includes "Main Stories" in the app "Love 365: Find Your Story," up until "Delivering the News"' FROM games WHERE igdb_id = 186572 ON CONFLICT (game_id, language_code) DO NOTHING;
