INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet of the Eyes', 'Planet of the Eyes is an action-puzzle platformer with a retro sci-fi inspired aesthetic and a mystery-driven storyline. At the outset of the game, the player - an exploration robot - starts his search for the source of a pulsing signal on the planet. Along the way, the robot negotiates multiple dangers, solves environment-based puzzles, and uncovers the truth about the Planet of the Eyes through the audiologs of a surviving crew member. The fate of both these survivors and the planet itself will hang in the balance as the player contemplates a destiny that was meant to be unavoidable.' FROM games WHERE igdb_id = 16313 ON CONFLICT (game_id, language_code) DO NOTHING;
