INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkness Assault', 'The number of missing in the city increased. People talk about the experiments on human beings. And now, only you can figure out if it was true. Especially because you have no choice. Mysteriously, you find yourself in a terrible location 40 meters underground. Your name is Katrine, and you do not remember anything about your past. But in the search for truth, try not to lose yourself.' FROM games WHERE igdb_id = 36149 ON CONFLICT (game_id, language_code) DO NOTHING;
