INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Magic Circle', 'You are the protagonist of an unfinished 1st person fantasy game, trapped in development hell. The designers (played by James Urbaniak, Ashly Burch, and Karen Dyer) are god-like, but so indecisive that they''ve given you no powers whatsoever. With the help of a mysterious disembodied voice (Stephen Russell) you must seize the tools of game development from these unworthy ''gods'', uncovering more of the darkly comic story as you go.' FROM games WHERE igdb_id = 17847 ON CONFLICT (game_id, language_code) DO NOTHING;
