INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxboy!', 'Box Boy! is a platform game in which players control a box-shaped character named Qbby as he makes his way through each level. The source of the game''s mechanics come from Qbby''s ability to spawn boxes out of his body, the number of which varies between each level. These boxes can spread out in whatever direction is possible to make various shapes and can either be carried or thrown and pushed around. The boxes have various uses, such as allowing players to reach high ledges or cross large gaps, holding down switches, or blocking deadly lasers. Additionally, by hooking these boxes onto a ledge while Qbby is still attached, he can pull himself up.
