INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lara Croft: Relic Run', 'Set shortly after Lara Croft and the Temple of Osiris, the game follows Lara as she goes in search of fellow archeologist Carter Bell. On her search, she uncovers a world-threatening conspiracy. Relics collected during play sessions unlock journal entries that reveal pieces of the story and make new locations available.' FROM games WHERE igdb_id = 15384 ON CONFLICT (game_id, language_code) DO NOTHING;
