INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rebel Galaxy', 'Rebel Galaxy is an action-packed, swashbuckling space opera. You''ll battle pirates, explore anomalies, befriend aliens, scavenge battle wreckage, mine asteroids, and discover artifacts. Choose your path as a roguish do-gooder, crafty space-trader or power-hungry privateer - or maybe a little of each! Buy larger and more powerful craft with your hard-earned credits, and outfit them with a variety of wicked weapons and defenses. Set in a galaxy of fantastic sights, and secrets to be found, Rebel Galaxy is above all a space epic of adventure, exploration, and combat.' FROM games WHERE igdb_id = 11719 ON CONFLICT (game_id, language_code) DO NOTHING;
