INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contract with the Devil', 'The unknown sends you a letter and invites to his house, promising to tell something very important about your daughter. But during the dinner with the owner of the mansion, the terrible thing occurred: as soon as you threw off the blanket from antique mirror, a mysterious evil force stole your only daughter Lisa! Right before your eyes, she disappeared inside a large mirror without a trace, and the only witness of these strange events who could shed the light - disappeared. Return 7 vices back to the Vault in order to help Sonya to save yourself and her daughter. Use the tips of a bogy Brownie - it will become your faithful assistant in this dangerous journey full of mysticism.
