INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Verge: Lost Chapter', 'Our hero has decided to get away from the urban bustle and out into nature to relax. On his way to his cabin, while anticipating the amazing sunsets, fresh air, the tranquility of the mountains, a heavy rain began to fall. His car breaks down in the middle of nowhere, the cold torrential rain dashing any hope of getting the car moving again. He hadn’t seen another person in hours, and as far as he could recall, there was nothing around…but for an abandoned building. He approaches it, seeking shelter, but is it really abandoned?' FROM games WHERE igdb_id = 34484 ON CONFLICT (game_id, language_code) DO NOTHING;
