INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crusaders of the Lost Idols', 'Crusaders of the Lost Idols puts players in charge of a band of fighters set in the fantasy world. Their mission is to form a mighty group of adventurers to take on waves of enemies as they rid the world of evil-doers, bad guys, terrible T-Rex, irritable escargot and Panda Claw. Yes, that’s right, a giant panda with lobster claws.
