INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apothecarium: The Renaissance of Evil - Premium Edition', 'During the Middle Ages a terrifying, mysterious disease raged across Italy. It killed thousands of people, whole towns and villages perished together. There were legends of a mythical town of Apothecarium, where the secret to defeating the disease was hidden.' FROM games WHERE igdb_id = 35136 ON CONFLICT (game_id, language_code) DO NOTHING;
