INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pahelika Secret Legends', 'A delightful adventure featuring exploration and puzzle solving. Long ago, the ancient book of legend, Pahelika, was used to defeat an evil warrior-king. In order to protect the book from misuse it was later hidden in a sacred temple guarded by six magical portals. As a descendant of the original wielder of the book, it is up to you to prove yourself worthy of the magical artifact…
