INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Else Heart.Break()', 'Sebastian has just landed his first job in the distant city of Dorisburg. He moves there to start his adult life and figure out who he really wants to be. Among a strange collection of people, hackers and activists he finds some true friends – perhaps even love. But can they stop the terrible deeds of the people ruling the city? And who will get their heart broken in the end?”
