INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Edge of Space', 'Suit up as an operative of the Ark Corporation, sent to the farthest reaches of the universe in search of habitable planets to terraform. However, after the long space journey you awaken from cryosleep to find that your ship has gone way off course and is disabled near a strange new world. With no choice but to descend to the surface and figure out how to survive long enough to complete your mission, you step into the escape pod.
