INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Pharma', 'What if you had it in your power to rid the world of disease, to improve the lives of millions, to ease suffering and cure the sick… and earn a tidy profit? As the head of your own Pharmaceutical Conglomerate you have this power resting in your hands. Will you use it for good?' FROM games WHERE igdb_id = 24396 ON CONFLICT (game_id, language_code) DO NOTHING;
