INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aima Online', 'Embark on an epic adventure in Aima, a 3D side-scrolling MMORPG. Choose your character from over five unique classes, including the Swordsman, Runeblader, and Assassin. While each class is gender-specific, you have the freedom to customize your character''s colors and appearance extensively. Unlock new moves, skills, and abilities to perform longer combos and unleash devastating attacks. Explore diverse dungeons in teams, collaborating to layer skills and conquer monstrous bosses. Join a guild, test your mettle in PvP battles, and unlock Guardian transformations for your character.' FROM games WHERE igdb_id = 62101 ON CONFLICT (game_id, language_code) DO NOTHING;
