INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sid Meier''s Starships', 'Sid Meier’s Starships challenges players to build a planetary federation by exploring the galaxy, expanding its influence and domain, researching futuristic technologies and engaging in deep, turn-based tactical space combat with an armada of uniquely customizable starships. Each new campaign will feature its own distinctive galactic strategy map of worlds with dynamically generated tactical combat missions that will enhance the game’s replay value. In addition, Sid Meier’s Civilization: Beyond Earth fans who purchase Sid Meier’s Starships will uncover cross-connectivity with the two games such that will enhance and expand the depth of both game experiences.' FROM games WHERE igdb_id = 8714 ON CONFLICT (game_id, language_code) DO NOTHING;
