INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anoxemia', 'Anoxemia is a story-driven exploration game that puts you in control of the scientist Dr. Bailey and his operations drone, ATMA. Search the ocean floor as you discover and extract samples from the bowels of the underwater caves. Danger lurks in each passageway, everything from poison drifts to powerful ocean currents, mines leftover from the war, and mobile machines running haywire. There''s also the ever-present risk of running out of oxygen. Fortunately, ATMA can help guide you to your destination using a few special tools and upgrades. Assuming you can find them, that is.' FROM games WHERE igdb_id = 9877 ON CONFLICT (game_id, language_code) DO NOTHING;
