INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rebuild 3: Gangs of Deadsville', 'Rebuild 3 is a strategy sim game with a good helping of narrative and dark humor. It''s a thoughtful game that''ll make you fond of your survivors before you send them to their deaths for the greater good. As you expand your fort to new buildings, you''ll decide between farms or fortifications, housing or hospitals, and make tough decisions to fend off raiders, illness, starvation, and madness. And the dead are still out there wandering the streets, hungrier than ever.' FROM games WHERE igdb_id = 16724 ON CONFLICT (game_id, language_code) DO NOTHING;
