INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dropsy', 'After a deadly circus fire shatters his world and tarnishes his name, Dropsy the Clown finds himself on a journey of self-discovery through a story that harnesses powerful themes of love and kindness. With his father gravely ill and the world turning its back on a once happy-go-lucky clown, Dropsy will need to help those in need, hug total strangers, and unravel dark and shameful secrets from his past on the way to redemption. Oh, and Dropsy can also talk to animals.
