INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario: The Music Box', 'Mario has heard rumours of an abandoned mansion that has been close to the Mushroom Kingdom for over a century. Any person who dares step into the mansion''s rooms, never returns. Mario and Princess Peach were supposed to investigate the strange place but Mario decided to go alone. Inside the home he finds a strange music box that was playing by itself. Little did he know that a "harmless" music box would''ve caused the home to try to eat him alive. Find out as you comb through a dangerous mansion and find out the story of it''s residents and how they met their fate.
