INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breach & Clear: Deadline Rebirth', 'A deadly new breed of human monster is on the rise, and it’s up to players to stop the infestation before it spreads. Breach & Clear: DEADline Rebirth is a new and greatly improved version of B&C: Deadline, the follow-up to Breach & Clear, the critically acclaimed hybrid tactical strategy game. The game gives players real-time control over a squad of four elite Special Forces tasked with tracking down information on the source of the infestation.' FROM games WHERE igdb_id = 36293 ON CONFLICT (game_id, language_code) DO NOTHING;
