INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero of the Kingdom II', 'You and your sister had finally found a safe haven in a small fishing village. But more troubles came soon after that. The threat of an unstoppable crew of pirates spread its shadow over the entire kingdom. Your beloved sister was kidnapped by the pirates and taken far away to lands unknown. You have no choice but to embark on a journey to save her. You must be brave. You will travel to the end of the world, helping people, fulfilling quests, learning valuable skills, and finding hundreds of useful items.' FROM games WHERE igdb_id = 13661 ON CONFLICT (game_id, language_code) DO NOTHING;
