INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors 4-II', 'Samurai Warriors 4-II is a hack and slash game and the enhanced version of the original Samurai Warriors 4. It is described as neither a continuation nor an Xtreme Legends expansion like previous games; instead, it provides a "different" focus of the same game. Players choose a character as their protagonist for a selected scenario, which has a different progression depending on the character selected. Dream Castle Mode, first introduced in Samurai Warriors: Chronicles 3 is also present in the game. The game adds one new character, Naomasa Ii, to the character roster.' FROM games WHERE igdb_id = 12279 ON CONFLICT (game_id, language_code) DO NOTHING;
