INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed: Syndicate - Gold Edition', 'London, 1868. The Industrial Revolution unleashes an age of invention, transforming the lives of millions with technologies once thought impossible. But industrialization only fattens the purses of a privileged few, while workers struggle to survive in the factories that make London the beating heart of the global economy— until an Assassin rallies to their defense, sparking an epic conflict that will echo throughout history. Create the world’s first organized crime family. Conquer the streets of London. Bring the ruling class to their knees. And rise to lead the London underworld in a visceral adventure unlike anything you''ve played before.
