INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nuclear Throne', 'Nuclear Throne is an action roguelike-like by Vlambeer about mutants fighting their way through a post-apocalyptic world. The radioactive waste in the world allows mutants to get ahead by mutating new limbs on the fly, the abundant availability of powerful weaponry make the quest to become ruler of the Wasteland one fraught with peril.' FROM games WHERE igdb_id = 3227 ON CONFLICT (game_id, language_code) DO NOTHING;
