INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parcel', 'Parcel is a multi-character cyberpunk puzzle game where your goal is to solve interlocking laser puzzles by using the unique abilities of different characters. The game can be played alone or cooperatively with friends. The game features over 120 unique puzzles and a level editor which enables the amount of playable content to grow to unpredictable numbers. A puzzling future awaits!' FROM games WHERE igdb_id = 17699 ON CONFLICT (game_id, language_code) DO NOTHING;
