INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valiant: Resurrection', 'Travel to the cloud land of Asteria, home of the mighty titans, and all types of magical creatures. It’s here where Argo and his dragon Golagros must go to restore the life of a fallen princess. With the help of the inhabitants, you must face the Fallen Titans and avoid the Judges, a shadow race, who watch over all of Asteria. Explore the lands of Sirenus Bay, God’s Garden, Whitebleak, Fort Ember, God Snare, and the mysterious Immortal’s Abyss. Are you brave enough for this adventure?' FROM games WHERE igdb_id = 35281 ON CONFLICT (game_id, language_code) DO NOTHING;
