INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vendetta: Curse of Raven''s Cry', 'Step into the boots of the vicious pirate Christopher Raven and get revenge on the men who killed your family and took your hand. Explore the Caribbean on land and sea, slaying your enemies with a combination of blades, bullets and cannon-fire. Vendetta’s free-flowing combat system allows you to dispatch your foes in a variety of brutal ways; use blocks, counters, parries, pistols, combos and devastating finishing moves utilizing Christopher’s hook to strike terror into the hearts of your enemies.' FROM games WHERE igdb_id = 14602 ON CONFLICT (game_id, language_code) DO NOTHING;
