INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Kill of the Week: Reborn', 'Zombie Kill of the Week: Reborn is a challenging, fast paced, 2D survival shooter! And when we say fast, we mean breakneck, flat-out, adrenaline fuelled fast! What’s different from the other shooters is your goal isn’t to run through levels and finish the game, but to survive for as long as possible under increasingly frantic conditions (we say as long as possible because ultimately you will die!).
