INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kerbal Space Program', 'In Kerbal Space Program, take charge of the space program for the alien race known as the Kerbals. You have access to an array of parts to assemble fully-functional spacecraft that flies (or doesn’t) based on realistic aerodynamic and orbital physics. Launch your Kerbal crew into orbit and beyond (while keeping them alive) to explore moons and planets in the Kerbol solar system, constructing bases and space stations to expand the reach of your expedition.' FROM games WHERE igdb_id = 3102 ON CONFLICT (game_id, language_code) DO NOTHING;
