INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prison Architect', 'The game is a top-down 2D construction and management simulation where the player takes control of building and running a prison. The player is responsible for managing various aspects of their prison including building cells and facilities, planning and connecting utilities, hiring and assigning staff, including a warden, guards, workers, and more. The player needs to recruit staff to unlock more aspects of the game. The player is also responsible for the finance, and keeping their inmates content.' FROM games WHERE igdb_id = 1338 ON CONFLICT (game_id, language_code) DO NOTHING;
