INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Factory', 'Sitting in front of a screen or TV you might think that the process behind filming and producing a movie is a piece of cake. Try and play Dream Factory first. With this Filming Simulator you will ‘dive’ headfirst into the busy world of movie making. Our approach is to look at the industry in an ironic way. We’ve reviewed many different samples and cliches of both the old and modern Hollywood Industry, and rediscovered the most memorable names who made the filming culture of 20th-21st centuries what it is today.' FROM games WHERE igdb_id = 34319 ON CONFLICT (game_id, language_code) DO NOTHING;
