INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancestor', 'A super fun puzzle action runner that will challenge your brain and dazzle your eyes. Venture across a dangerous landscape riddled with traps and enemies. Defeating foes and overcoming obstacles will earn you currency chips that you can spend on lavish cloaks and various orbs. As you travel further into the unknown, your surroundings scale in difficulty, demanding quick thinking and swift reflexes. 
