INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rustbucket Rumble', 'Rustbuckle Rumble is a side-scrolling, team-based, arena combat game - WITH ROBOTS! Inspiration for the mechanics was taken from classic run and gun games mixed with more modern, class-based, multiplayer shooters. It’s capture-the-flag where the players are the flags. Games are fast as you battle your opponents, turn them into scrap, and return them to your base, recycling them for parts before the other team can stop you. Your base uses the robot parts to create a giant robot super weapon that is unleashed to destroy the enemy’s base!' FROM games WHERE igdb_id = 35699 ON CONFLICT (game_id, language_code) DO NOTHING;
