INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puramai Wars', '“Modesty, fairness and grace”: That’s the motto by which Chihaya and his sisters Kyouko and Mei were brought up with by their strict father. Their family was well-respected in the neighbourhood; You could say they’re the ideal family. Due to an unexpected event, they ended up sharing a house with the family of one of their parents’ co-workers. Chihaya heard that there were three beautiful sisters and was looking forward to living together with them, but it turns out that their nature is totally opposite of their family!' FROM games WHERE igdb_id = 60174 ON CONFLICT (game_id, language_code) DO NOTHING;
