INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Cells', 'Look through a microscope and discover a small world made of ever expanding cells of 3 colors. Launch a cell against one of the same color to make them both disappear. Launch it against a cell of a different color and a new cell of the third color will be created. But beware! Cells are aging and become sick and dark. They might spread out and contaminate the whole system. Create white cells to help you cure this disease before it’s too late. Try to stay alive the longer you can and beat your score or your friends’ high scores.' FROM games WHERE igdb_id = 28110 ON CONFLICT (game_id, language_code) DO NOTHING;
