INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CodeSpells', 'When we were young, wizards like Gandalf and Dumbledore struck a chord in our minds. We spent hours pretending to be wizards and casting epic imaginary spells. Now, we want to bring that kind of creative freedom to video games. Instead of giving the player pre-packaged spells, CodeSpells allows you to craft your own magical spells. It''s the ultimate spellcrafting sandbox. 
