INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet Set Luis', 'En esta nueva aventura controlaremos a Luisdel a lo largo de una semana de su vida, ayudándole a esquivar peligros cotidianos y visitando lugares populares de nuestra tierra (el Ensanche, la fábrica de harinas, los bosques de Caudete…) mientras recoge aquellos objetos que le sean útiles para lograr su ansiada meta: disfrutar del fin de semana con su chica en la Costa Blanca. 
