INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cookie Champion', 'In Cookie Champion players must guide an adorable chocolate chip cookie named Chewy across a picnic table covered in spilled milk. Equipped with only a pair of drinking straws, users have to swiftly tap each straw in order to balance the clever cookie as he attempts to walk as far as possible. But don''t let him fall or he''ll end up as dessert!' FROM games WHERE igdb_id = 175187 ON CONFLICT (game_id, language_code) DO NOTHING;
