INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fiends of Imprisonment', 'Randy''s country went to war with the world''s nuclear super power. Their enemies have captured a group of over 900 soldiers and are threatening to kill them all... They''ve put them in to a military imprisonment... a heavily guarded one... sounds familiar? The government asked Randy... They begged him... It was obvious that he was their only hope! Will you save their souls? Will you follow Randy one last time? Through HELL and back? Find those prisoners and beat their Fiends of Imprisonment.' FROM games WHERE igdb_id = 34265 ON CONFLICT (game_id, language_code) DO NOTHING;
