INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Town: Hospital', 'Ever wanted to play as a doctor, nurse or patient? Bandage hands, use statoscope, check for fever and even help dad to rush mom in to the baby delivery room! From the makers of My Town comes the largest most kids friendly realistic doll house game, My Town : Hospital. It’s a hospital like not other, where kids can interact with real checkup rooms such as MRI and X-ray room, a small emergency room and even a recovery room. My town : Hospital has it all.' FROM games WHERE igdb_id = 88955 ON CONFLICT (game_id, language_code) DO NOTHING;
