INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This is Forever', 'This is Forever is an atmospheric symbolic game, in which you explore a relaxing world while uncovering clues by finding missing memories in the form of personal objects. Music guides the experience, evolving and changing as you progress. Each shift in music helps to interpret the meaning of each stage. It is my hope that this can speak to individuals facing difficult times, loss, and facilitate positive growth and thought.' FROM games WHERE igdb_id = 148292 ON CONFLICT (game_id, language_code) DO NOTHING;
