INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Heroes Online', 'Chaos Heroes Online is a free to play MOBA known as Chaos Online in the East, inspired by the Chaos mods for DOTA maps in Warcraft. Standard MOBA/DOTA players may find a few differences: items can be purchased anywhere on the map, consumables are critical, instant teleportation, and no wards. CHO encourages grouping up and discourages passive farming, and has a strict 50 minute time limit on matches. Scoring for matches is based on kills, collective team levels, objective completion, and more. CHO also includes questing, from daily objectives to hero quests. Leveling up will also grant you a free hero for three days.' FROM games WHERE igdb_id = 286427 ON CONFLICT (game_id, language_code) DO NOTHING;
