INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freshman Year', 'Freshman Year is a vignette game about an ordinary night in the life a college freshman named Nina. Nina''s best friend Jenna invites her to meet up at a local bar with some classmates. Jenna is sort of flaky though, so Nina has to navigate the party by herself. You play as Nina, texting with her friend Jenna as you mingle, dance, drink and wait.' FROM games WHERE igdb_id = 35405 ON CONFLICT (game_id, language_code) DO NOTHING;
