INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannibal Island', 'Live the life of a survivor who lost his parents at age 12 and was adopted by the wily Mr. Francis. Survive the cold nights and constant attacks. Build shelters to keep protected and tools to assist in the tasks, try to create alliances with other survivors, explore this new world to find new ways to stay alive in a survival game in first person. Just a warning to survivors, the cannibals will not use only fists to attack, they will be intelligent and lethal. Very careful with nightly ambushes and long distance shots.' FROM games WHERE igdb_id = 13990 ON CONFLICT (game_id, language_code) DO NOTHING;
