INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Private School Days', 'Enjoy the school sim at its best with all the privileges of a "Private" education! Start with a student of your own creation, switch characters at any time, and save your changes to all 10 classes as well as the teachers and civilians. Have fun recreating your own real-life classmates, or simply play God by cheating your way to the life you always wanted. And with no sponsors paying your way, you can enjoy every minute of every day without any interruptions. Private students also benefit from a more continuous experience that never ends until you want it to. If you fail to graduate, repeat the year. If you get expelled, walk the streets as a civilian. Even death holds no fear for those with "private" health care! 
