INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Visitor 3', 'Commander Moss and his crew are back with another dangerous mission. An Omega 1 prisoner transport ship carrying two prisoners sent a distress beacon before disappearing from radar. President Gooman decides to send Slug, Scar, Commander Moss and his new human assistant, Head, to the ships last known coordinates. Moss and his crew must find this ship and rescue any survivors. Once there, Commander Moss soon realizes, there is more going on than a disabled ship. A new life form emerges and puts everyone on board the ship at risk.' FROM games WHERE igdb_id = 232764 ON CONFLICT (game_id, language_code) DO NOTHING;
