INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Legends', 'The Rise of Dragon Tide Update will bring brand new school and gameplay to our fans! Are you ready for the Chaos Legend ultimate war? As the pride of the Dragons, new school Dragon Tide is in charge of storm and thunder with vast attack range and great survival ability. Useful skills of displacement and controls make her a must-play character in the new version. The level cap has been pulled up to 130 while Deity Refine, Soul Sealing and Treasure Instances Auto-Loot Functions can strengthen your character as much as possible. The Country Swap function is available, which will add uncertainty to Guild Team Instance and Crystal Mine Seize War. Only the most powerful player could lead your team to victory and glory!' FROM games WHERE igdb_id = 93640 ON CONFLICT (game_id, language_code) DO NOTHING;
