INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saenai Heroine no Sodatekata: Blessing Flowers', 'Saenai Heroine no Sodatekata -blessing flowers- is a Japanese visual novel based on the Saenai Heroine no Sodatekata light novel franchise. The novel has multiple routes featuring the different heroines of the game. One of the features of the game is an "Otaku Mode" system, where the player can lend the heroines different light novels, games or anime DVDs to change their dialogue and personality. The game utilizes Live 2D software, which moves the characters with CGI, but retains their two-dimensional look.' FROM games WHERE igdb_id = 11777 ON CONFLICT (game_id, language_code) DO NOTHING;
