INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PuniTy', '"PuniTy," as Qureshi calls it, is a project designed as part of a 3D modelling workshop that Qureshi will be teaching in September. Originally, Qureshi was going to create a simple, non-terrifying apartment due to its simultaneous simplicity, familiarity and variety of objects it would contain. However, since the workshop is aimed at game developers, Qureshi decided to attempt to recreate the infamous haunted hallway. You can see screenshots of his impressive work above, or visit his page for a step-by-step breakdown of how he managed this impressive feat (in four weeks by himself, no less).' FROM games WHERE igdb_id = 26508 ON CONFLICT (game_id, language_code) DO NOTHING;
