INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gravblocks-plus', 147964, '2015-02-26', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9n7n.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GravBlocks+', 'GravBlocks+ is a new and different take on the traditional match-three style puzzle game. Rather than building combos the old fashioned way, the gameplay is designed around strategic planning and changing gravity and earn Score Multipliers. However, it''s not as easy as it sounds! The walls are filled with Destruction Hazards, and dropping blocks into those Hazards instantly resets the Score Multiplier. Using a Wild Block closes the Hazards making gravity changes safer, but players need to plan well for these moments! This exclusive Wii U eShop game features: Five gameplay modes with animated backgrounds! Saving high scores for Challenge and Zen modes! 80 Accomplishments, with nearly 20 unlockables! Insane alien abduction story with over 90 levels! 150 challenging puzzles! Off-TV play, left or right-handed options, and color-blind friendly!' FROM games WHERE igdb_id = 147964 ON CONFLICT (game_id, language_code) DO NOTHING;
