INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Help Newton', 'In this game, the opportunity is offered for you to help Newton to gain inspirations for his work. In every scene Newton goes, an apple is given by the apple sprite. You need to lead the apple to pass all the obstacles to reach Newton. The game world is based on the simulation of classical physics, which is founded by Newton''s theory. All the funs you have to discover in game.' FROM games WHERE igdb_id = 197228 ON CONFLICT (game_id, language_code) DO NOTHING;
