INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Erwin''s Timewarp', 'Erwin''s Timewarp is an Adventure game in which the player controls the dog named Erwin, the pet of the scientist Dr. Zachory. He has invented a time machine with that Erwin was transferred to the time 1984 by accident. In order to come back to present time Erwin has to find parts of a time machine. For this task a lot of puzzles have to be solved.' FROM games WHERE igdb_id = 34689 ON CONFLICT (game_id, language_code) DO NOTHING;
