INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battles of the Ancient World', 'The ‘Battles of the Ancient World’ game system is a tactical simulation of some of the greatest and most important battles from 1457 B.C. to 378 A.D.. Each scenario features one of these great battles and players may play as either side. The game has been designed to ensure maximum playability and historical accuracy, in that order. There are over 55 different units across all the missions, ranging from elite Roman Legionaries, to Persian Scythed Chariots. Each unit has its own unique ability that you need to take advantage of in order to win each battle.' FROM games WHERE igdb_id = 67597 ON CONFLICT (game_id, language_code) DO NOTHING;
