INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Object: Detective Wiltshire Kingdom, The Book is About 33 Knight', 'Don''t miss the chance to play an exciting new game "Detective Wiltshire Kingdom" in "I''m looking for" genre. In Wiltshire county an outrageous robbery happened. A book about 33 knights was stolen from Count Matthew''s house. The book tells the legend of the 33 knights who defended the county. Puzzle over lots of intricate puzzles. The fate of the kingdom is in your hands in this fascinating new game.' FROM games WHERE igdb_id = 200199 ON CONFLICT (game_id, language_code) DO NOTHING;
