INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kitaria Heroes: Force Bender', 'Force Bender tells a story of the adventure of a sword magician named elena. she lost her family because of a mysterious dark magician''s deeds. The dark magician also spreads chaos and nightmare to the land. Elena trained hard in order to take revenge and bring back peace to the land. Taste the full action RPG (Role Playing Game) as you wipe out monsters in your journey! Feels the unique action as you play as Elena with her variety of magics and sword techniques! Help Elena defeat the dark magician!' FROM games WHERE igdb_id = 38961 ON CONFLICT (game_id, language_code) DO NOTHING;
