INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Dragon Simulator', 'Rain down fire from above as an all mighty Dragon! Join an age old battle between beast and man as you face off against Orcs, Humans, and legendary monsters from mythology! Recruit, raise, and customize your dragons, destroy castles and villages, collect treasure, and battle for your life against fierce bosses like the undead Bone Dragon!
