INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('knights-of-pen-and-paper-ii', 10126, '2015-10-20', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21b2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arn5a.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knights of Pen and Paper II', 'Prepare to inhabit a world of chivalry, class warfare and off-beat pop references. Knights of Pen & Paper II is a turn-based, retro style, pixel-art adventure full of danger, intrigue, death, and saving throws! Players assume the role of a group of teenagers, playing a classic pen & paper RPG to overcome dicey situations. As both party and game master, they get to assemble both their characters, and the challenges they will face. Select among mighty classes like Wizard, Thief or Warrior; proud races like Dwarf or Elf; and snark-slinging players like Goth, Lab Rat or Rocker. Choose quests and combat encounters, delve dungeons, craft powerful items and watch in horror as your muscle-packed barbarian rolls a one on his body check. Together, face the greatest threat the campaign world has ever faced: The new rules edition.' FROM games WHERE igdb_id = 10126 ON CONFLICT (game_id, language_code) DO NOTHING;
