INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Camel Up', 'Witness the craziest camel race of all time, as things really go topsy-turvy when camels stack up and entire pyramids turn upside down. As members of Egyptian high society, you gather in the desert with one simple goal: to gain the most money by backing the right camel to win a leg or even the entire race. However, in this race, it’s not just the lucky ones who can beat the odds. Reading the dynamics of the race and having a good sense of timing is just as important when it comes to backing the right camels and taking the victory.' FROM games WHERE igdb_id = 197715 ON CONFLICT (game_id, language_code) DO NOTHING;
