INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kill the Ragdoll Stickman 2', 'Give him pain!!! Boss the ragdoll man around and give him as much pain as you can. Push him off mountains, off skyscrapers, backflip him in to turbo cars, and even throw him in to an asteroid. This is bone breaking, dummy snapping physics fun at its best. Lots of levels to make the fun last, hilarious situations, and bags of re-play value. Just tap the ok buttons when he''s standing to dismount him.' FROM games WHERE igdb_id = 175549 ON CONFLICT (game_id, language_code) DO NOTHING;
