INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyper Rift', 'Hyper Rift is a visual gamebook adventure that draws inspirations from science fiction mysteries. We''ve crafted an original science fiction story that blends real science with imaginations and present choices that lead to far-reaching consequences. It also features number puzzles, situational puzzles, multiple endings and interesting characters that can save your life or betray you in critical moments.' FROM games WHERE igdb_id = 273862 ON CONFLICT (game_id, language_code) DO NOTHING;
