INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Eiyuu Musou', 'Touhou Eiyuu Musou (English: Eastern Heroes Unrivalled) is the second game, developed by Kanagawa Denshi Gijutsu Kenkyuujo and Strawberry Bose, and based upon Shin Sangokumusou a series of action games created by Omega Force and Koei. Similar to Shin Touhou Musou, there is no specific storyline and the player chooses one of 12 playable characters, explore 50 stages going after fairies, kedamas, UFOs and a powerful boss that awaits every five stages. Each level has different terrain and random enemies. As the player collects more point items and experience, new skills can be unlocked. The game also supports two player cooperative mode via network feature.' FROM games WHERE igdb_id = 250586 ON CONFLICT (game_id, language_code) DO NOTHING;
