INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Soldiers: War Chest', 'Toy Soldiers: War Chest is similar to the previous games where players prevent enemy units from reaching the toybox by building and upgrading turrets. In War Chest, turrets can be improved by upgrading armor, fire rate and damage separately. The enemy AI is improved as well. For example destroying a bridge will cause ground units to take a different path to the toybox. Certain units have the ability to heal nearby units and some will focus on destroying any placed turrets.
