INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dolphin Up', 'A fun, vibrant, 2-minute game with surprising depth, Dolphin Up lets you do amazing tricks with a porpoise. Successful flips, spins and tailslides build speed, allowing you to jump higher and soar into the stars. Perfect your landings and chain your tricks together to form huge combos, discover new possibilities and work your way up the leaderboards. A must-have classic.' FROM games WHERE igdb_id = 31155 ON CONFLICT (game_id, language_code) DO NOTHING;
