INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '6 Love Dominoes', 'When was the last time you slammed some dominoes? In the fast paced game of life, sometimes there just isn’t enough time to enjoy the little things. 6 Love Dominoes changes all of that, making it easy to have a quick game on your daily commute. Create an avatar using a variety of facial features and hairstyles, personalize it with your chosen nationality, and represent yuh yard by winning games and climbing the leader boards. See what your skills can do for your individual rank.' FROM games WHERE igdb_id = 88421 ON CONFLICT (game_id, language_code) DO NOTHING;
