INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dice Town Mobile', 'Dice Town Mobile is the poker game of dice and land grabs, where your roll determines your luck, not the other way around. Roll the poker dice and build the hand that gets you what you want. Rob the bank, mine for gold, or settle the land, but be smart, because only the best rolls can win, and there''s always someone willing to steal your hard-won rewards right out from under you. If your hand isn''t what you hoped it would be, you can always pay to try again - as long as you can afford it, that is.
