INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glider: Soar the Skies', 'Experience mobile flight simulation like never before. Glider features some of the most advanced graphics in mobile gaming. Soar over the hills of Switzerland and climb the ranks as you locate thermals in an attempt to stay aloft the longest. Fly along the edge of the hills and share the thermals with the eagles that inhabit the area. Observe detailed scenery as you become part of the world of glider pilots. Glider flying requires you to utilize the weather to your advantage as apposed to flying through it. Master the art of glider flying and soar for hundreds of miles without any fuel.' FROM games WHERE igdb_id = 175057 ON CONFLICT (game_id, language_code) DO NOTHING;
