INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senran Kagura 2: Deep Crimson - Double D Edition', 'The naughty yet very nice ninja girls of the SENRAN KAGURA universe return to the 3DS in a fresh, new 2.5D side-scrolling brawler. Featuring the series'' trademark high-flying, clothes-ripping battle mechanics, SENRAN KAGURA 2: Deep Crimson follows the events of SENRAN KAGURA Burst, sending all 12 of the original cast members on another supernatural martial arts adventure through modern Japan. For the first time in the series, shinobi can fight in pairs, covering each other''s backs or combining special techniques as needed, or fight alone to give their partners time to recover after bouts of intense combat. One player can control both team members, switching back and forth at will, or two players can fight together in co-op mode, side by side.' FROM games WHERE igdb_id = 47690 ON CONFLICT (game_id, language_code) DO NOTHING;
