INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarCraft II: Legacy of the Void - Collector''s Edition', 'StarCraft II: Legacy of the Void is the final chapter in the epic scifi storyline spanning the StarCraft II trilogy. Players will guide the powerful Protoss in the epic conclusion to Blizzard''s award-winning RTS series and aim to unite the three races in the ultimate battle for survival against an ancient evil threatening all life in the universe. Featuring new units and the introduction of new cooperative and multiplayer modes, Legacy of the Void is the ultimate strategy experience and StarCraft at its finest.
