INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broadsword : Age of Chivalry', 'Broadsword: Age of Chivalry boasts turn-based strategy gameplay as players move from mission to mission in the Middle Ages. Command one of four different armies: the English, The French, the Spanish, or the Hapsburgs in this exciting PC game. Lead different types of units into battle -- from archers, knights, pikemen and catapults with special units per nationality. Control special ''heroes'' units such as Henry III, Joan of Arc and El Cid, among others whose special ''hero'' powers can affect the entire battlefield. Set in medieval Europe.' FROM games WHERE igdb_id = 17618 ON CONFLICT (game_id, language_code) DO NOTHING;
