INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Incredible Dracula: Chasing Love', 'Vampires have gotten a bad rap. Take Count Dracula for instance. People think all he wants to do is suck their blood, but in truth, he wants the same things everyone else does: food, shelter, and love. He won''t settle for just any woman, though, so when a man-hungry princess takes a liking to him against his wishes, he does the only thing a red-blooded (or an undead) male can do: run!' FROM games WHERE igdb_id = 53226 ON CONFLICT (game_id, language_code) DO NOTHING;
