INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider Solitaire', 'You might know the rules of Spider Solitaire, but let us remind them just in case. To solve the patience, create descending “runs” of cards. The order goes from King to Ace, and has to be of the same suit to be discarded. On the tableau, single cards can be moved between the columns regardless of their suit or color, but only same-suit cards are allowed to be moved as a group. If no moves are available, you may deal another row of cards, as long as there are no empty cells on the table. Your final score for a game of patience depends on the number of moves, session time and the difficulty mode.' FROM games WHERE igdb_id = 91178 ON CONFLICT (game_id, language_code) DO NOTHING;
