INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infinite Space III: Sea of Stars', 'Sea of Stars continues the Infinite Space series of games that defined the genre of short-form space roguelikes in Strange Adventures in Infinite Space (2001) and Weird Worlds: Return to Infinite Space (2005). It compresses a galaxy-spanning starship adventure into the space of a single sitting, but as the game world is randomly generated each time you play, you will keep coming back for more. There is enough variety in items, aliens and special encounters that you will always discover something new - no two sessions play the same.
