INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runes of Brennos', 'In Runes of Brennos, you take control of a mighty druid seeking to seize power. Draw magical runes on the screen and see their power vanquish your opponents. Memorize and harness combos as you develop your skills. Understand the strengths and weaknesses of the runes to unleash their full potential. The road to power is a dangerous one, but with the right combination of strategy and skill the throne could be yours!' FROM games WHERE igdb_id = 17977 ON CONFLICT (game_id, language_code) DO NOTHING;
