INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Depths 2 RPG', 'Endless Depths 2 is a rogue-like role-playing game that holds true to classic features such a randomly generated dungeon levels, a myriad of class/race combinations, a bunch of treasure to discover and a one-life-one-death difficulty level that can be quite addicting. In addition to what might be expected in a rogue-like RPG, Endless Depths 2 adds a level of persistence to the genre that allows for item farming, crafting, and even increased difficulty levels should a character make it to the end.
