INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Gates', 'Dark Gates is a game which tries to capture classic tabletop RPG experience. As a player you need to assemble a party of six heroes, select spells for them and send them on the quest to the labyrinth. Somewhere in that maze an evil mage created Dark Gates and now gates are open. Your party have to find and destroy those gates as darkness pours into this world through them.' FROM games WHERE igdb_id = 36166 ON CONFLICT (game_id, language_code) DO NOTHING;
