INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1942 Pacific Front', '1942. World War 2. You and your troops are on duty near the Pacific – and there can only be one winner… The battle continues after 1941 Frozen Front – and this time, it’s all about naval warfare! Join the navy and fight to win the battle of your life! Own the battlefield and send your soldiers to the frontline. Military combat at its best! Choose the right tactics and use your commando to defeat the enemy! Lead the U.S. Army on their campaign or command the Japanese forces on their mission! Take out enemy alliances with infantry, artillery, tanks, warplanes, battleships and submarines and earn your stripes as an ingenious commander at the PACIFIC FRONT' FROM games WHERE igdb_id = 109016 ON CONFLICT (game_id, language_code) DO NOTHING;
