INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TOBAFCASS', 'TOBAFCASS (Thief of Bagdad - A Flying Carpet Arabian Side Shooter) is a side shooter with unique visual style and characteristic electronic music. For both the story and visual style I took inspiration from "The thief of Bagdad" a 1924 classic silent adventure movie with Douglas Fairbanks. Game mechanics are of classic ultra-hard side shooter. In particular I was inspired by "Agony" a beautiful yet unforgiving Amiga game from the 90s.
