INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harold', 'Harold is a singleplayer sidescrolling platformer with an emphasis on the high quality, hand-drawn style of classic animated films. You play as Gabe, the guardian angel responsible for guiding Harold through the multiple paths of each map, constantly saving your human charge from imminent death by manipulating obstacles in different environments. To edge out the other runners and prove your angelic abilities you''ll need every ounce of cunning and foresight you can muster, because your greatest hindrance is the oafish clumsiness of Harold himself!' FROM games WHERE igdb_id = 7865 ON CONFLICT (game_id, language_code) DO NOTHING;
