INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime is Sexy', 'Inspired by the Jalloo 2015 Game Jam theme, “Is this Legal?” our game submission satirically questions and challenges several official and unofficial laws within games, the game industry and the game jam itself. We lampoon some of the current directions and movements in the game industry with regard to profitability, privacy, independent development, and intellectual property controversies. After a few quick set-up steps, players can choose one of 1000 possible games from a list of randomly generated titles and enjoy the truly mind-blowing graphics that await. Each unique game experience is only available once and may just challenge your notions of what is “legal” in terms of games and their possible social meanings. What are you waiting for?... DO IT!!' FROM games WHERE igdb_id = 135401 ON CONFLICT (game_id, language_code) DO NOTHING;
