INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Playing History: Vikings', 'Navigating Erik in his journey from cradle, youth and eventual grave; you experience his journey towards becoming a true Viking within an interactive environment. It is times of change as the old beliefs are challenged by a new God and trade routes mean contact with people from strange lands. The game focuses on civilized trading as well as the faith and brutality of the viking era; a time when Christianity arrived in the North and became the dominant faith. 
