INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Save Your Mother', 'Alice Andersson, a world-renowned scholar, faces a dilemma of grand proportions when her mother falls gravely ill. No traditional cures have been able to save her; not even the most unconventional methods have worked! Join her as she discovers the legend about the Elohim Cube, a mystical artifact that might be their only hope. Long lost to the sands of time, the Cube is said to possess incredible healing powers. Over the ages, many have attempted to retrieve the cube, but to no avail. All were foiled by the long and arduous path that leads to the cube, and in turn, salvation. Will you be able to unravel the mysteries of the Elohim Cube?' FROM games WHERE igdb_id = 33944 ON CONFLICT (game_id, language_code) DO NOTHING;
