INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Helena''s Flowers', 'After her elopement with the neighboring Wilusan princess, Achaea declares war on Wilusa resulting in a years-long bloody conflict. As the war is drawing to a close, Helena is escorted back to her rightful place in Achaea. However, something goes wrong and their ship crash lands on a desolate tiny planet, killing everyone on board except for Helena and a single soldier.
