INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'School Days', 'The prison has closed down and re-opened as a high school, but the challenge to survive and thrive remains the same! Live every hour of every day in real-time - from getting out of bed in the morning to attending a timetable full of classes, as you explore a city filled with interactive props. Picking up knowledge from each class helps you answer real questions in 10 different subjects, as you work towards the grades you need to graduate. But with over 100 fellow students walking the halls, an equally important popularity contest decides whether your days are filled with fun or fear.' FROM games WHERE igdb_id = 135488 ON CONFLICT (game_id, language_code) DO NOTHING;
