INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'American Dad! Pinball', 'In American Dad! Pinball, you’ll explore the Smith family residence and Roger''s Place in a frantic mini-playfield, bullseye shots with Stan at the Fun N'' Gun Shooting range in a first-person mini-game, assume Roger''s various Personas in different game modes, and manipulate the National Threat Level, changing the way missions will play out!
