INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The BoX', 'The Box takes the speed of a beloved platformer of old and mixes it up with color based powers and adaptations. Here you will find a mystery only you can solve with complex challenges along the way to guide you in finding the answer. Use the 6 colors at your disposal to take on the treacherous Box and find your way to freedom. Not all data is perfect. Lead our spherical little hero through The Box as he aims to find a world where its curves aren''t so out of place.' FROM games WHERE igdb_id = 33963 ON CONFLICT (game_id, language_code) DO NOTHING;
