INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Smurfs', 'After a walk in the forest, the Smurfs come back to find their village destroyed. Gargamel has accidentally released a dragon, transformed by one of his mysterious experiments! Will you be able to find an antidote and cure the dragon to restore peace? Papa Smurf is counting on you to save the day! Play 12 Fun Mini-Games Help the Smurfs in their quest to save the day. Keep the Smurfs Spirit High Cooking, playing music, painting... The Smurfs are always ready for good fun. Rebuild the Smurfs'' Village Customize the village and make it your own!' FROM games WHERE igdb_id = 23482 ON CONFLICT (game_id, language_code) DO NOTHING;
