INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flip Flap', 'This game is a port of the popular mobile phone game, Flappy Bird. The game is fairly simple: You control a bird (or in this version, Opa-Opa) and tap the screen (press 1 or 2) to flap your wings and go up a bit, but gravity will quickly pull you back down. The aim of the game is to fly through the small openings in an endless stream of pipes without touching a pipe or the floor. Each set of pipes you pass gives you 1 point. The physics of the game makes it quite challenging, and it is fun to compete with others for the top score.' FROM games WHERE igdb_id = 218076 ON CONFLICT (game_id, language_code) DO NOTHING;
