INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '.Decluster Zero: Bullet Nocturne', '.Decluster Zero" is a Japanese style bullet hell shooter featuring neo-retro dot graphics. This game offers modern-classic bullet hell gameplay and traditional Japanese beautiful bullet patterns. You''ll have new bullet hell experiences with bullet-canceling system. 
