INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amaranthine Voyage: The Tree of Life', 'During your career as an archaeologist, you firmly believed that the Tree of Life was simply a myth. However, once you uncover a magical artifact, you open brand new worlds of possibility. You''ve whisked away to a lush world that is slowly being poisoned by a mysterious dark force. Your artifact is the key to restoring this beautiful world, but dark forces stand in your way. Protect the artifact and save this dying world in Amaranthine Voyage: The Tree of Life, a thrilling Hidden-Object Puzzle Adventure game.' FROM games WHERE igdb_id = 58029 ON CONFLICT (game_id, language_code) DO NOTHING;
