INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soushuu Senshinkan Gakuen Bansenjin', 'This follows the grand ending in Hachimyoujin, where Yoshiya doesn’t confess to anyone. Yoshiya’s group are now in their second year at Senshinkan Gakuen, joined by new students Nobuaki and Shizuno. There were a few more hiccups along the way, but every day is full of laughs and smiles. No one thought that it would change, but while devoting all their time preparing for the culture festival, they happened upon a secret of the school and were confronted with a nightmare which eroded reality. They didn’t have any special abilities to combat these strange occurrences, but then their inner elements awakened and the wheel of dreams begin to turn once more.' FROM games WHERE igdb_id = 137082 ON CONFLICT (game_id, language_code) DO NOTHING;
