INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luminosity', 'Luminosity is a fast paced arcade game. You take the control of a space ship and your objective is to close off the enemy drones and conquer a certain percent of the map in order to blow them up. Things quickly escalate and you face an increasing number of unique and challenging enemies and environments all trying to destroy your laser and blow your ship to pieces. To your aid you have a wide range of different Power Ups as well as the ability to upgrade your ship permanently between games. With randomly generated backgrounds and levels, the arcade mode stays fresh and new. Combined with the campaign this allows for endless hours of exciting gameplay.' FROM games WHERE igdb_id = 35836 ON CONFLICT (game_id, language_code) DO NOTHING;
