INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yorbie: Episode 1 - Payback''s a Bolt', 'Play as Yorbie and fight your way through an all-out bot onslaught with epic boss battles in this fast-paced 3d action adventure. Upgrade your weapons and enhance them with stacking bonuses to suit your playing style. Try out as many combinations as you like with the ability to re-customize weapons at any time in the weapon store. Scavenge components and bonuses from enemy bots, or even steal them from other players when they''re not looking. Hey, who said life was fair?' FROM games WHERE igdb_id = 22085 ON CONFLICT (game_id, language_code) DO NOTHING;
