INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Patty & Mr. Miles', 'The game takes place in Rinu Village - a cute little town where everything is peaceful, even if all the boys in the village have the heads of animals. This is all thanks to a mysterious witch, who lives up in the nearby spooky tower. Miles, unhappy with his own particular change into a rabbit, decides that he and his girlfriend, Patty, should go to the tower and confront this witch. However, with so many relaxing and fun things to do, between interacting with the villagers, going fishing, growing vegetables, and fighting dragons, Miles and Patty may find themselves distracted from their original goal.' FROM games WHERE igdb_id = 150218 ON CONFLICT (game_id, language_code) DO NOTHING;
