INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Elemental Prince', 'It’s a lazy afternoon at your high school, so after class you take a nap at your desk and when you wake up, you feel strange because the dream you just had ended abruptly. A sudden wave knocks you over and when you get up again, you’re not where you used to be. That odd occurrence has transported you to another world, a land belonging to elemental spirits. Soon you’re confronted with a couple of spirits that are not too happy to see a human in their domain. Who will be the unlucky (or lucky) one to look after you?' FROM games WHERE igdb_id = 299018 ON CONFLICT (game_id, language_code) DO NOTHING;
