INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rewind: One Last Chance', 'Unravel the mysteries of the Rewind in this suspenseful interactive experience in which truth is on trial. When Commander Kole Zamon is captured by those he terrorized, he is put on trial for crimes against humanity. But the Commander’s crimes are not the only thing on trial. His love for his daughter is tested. His loyalties are challenged. His religious beliefs are called into question. Beneath the surface of this Rewind—this mysterious trial—lurks a world of intrigue, a world that needs to be uncovered. In an ever-unfolding plot that twists and turns, the path to truth must be found.' FROM games WHERE igdb_id = 197736 ON CONFLICT (game_id, language_code) DO NOTHING;
