INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stella Glow', 'Stella Glow is strategy RPG for the Nintendo 3DS system developed by Imageepoch (Luminous Arc franchise). As most reluctant heroes do, Stella Glow protagonist Alto starts as a country boy in a small town. One day, he hears a song coming from the forest (which is odd, since song has been absent on the planet for thousands of years), where he discovers the lone Hilda. But after the chance encounter, Hilda reveals she''s the Witch of Destruction, hellbent on destroying the world with her harbingers. As Hilda is about to destroy Alto''s hometown, he and Lisette are rescued by the Knights of Regnant Alto will encounter the Regnant Knights and whisked back safely to the kingdom. Alto joins the 9th Regiment for the sole purpose of reuniting the rest of the witches to stop Hilda.' FROM games WHERE igdb_id = 11459 ON CONFLICT (game_id, language_code) DO NOTHING;
