INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewel Rotation', '"Jewel Rotation" is a fun and addictive puzzle game. It features: ✔ Three game modes: Beginner, Expert and Infinite ✔ HD graphics ✔ Tutorial for an easy start! Instructions: The board consists of four side-to-side layers filled with sparkling jewels. You have a quota to clear a number of specific kinds of jewels. You clear jewels by rotating the layers so that four of the same jewels line up. When you get a four of a kind, those jewels vanish and are replaced by more jewels. If you meet your jewel quota, you go to the next level for a tougher puzzle. You also have a time limit, so you better get those jewels out of there quickly!' FROM games WHERE igdb_id = 38668 ON CONFLICT (game_id, language_code) DO NOTHING;
