INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Kart: Speed Strife', 'The game features 12 characters, 8 of which are playable from the start. There are 16 tracks split up into four cups. If you get a trophy in one of the cups while playing in Grand Prix mode, you will unlock its respective characters. Additional to the Grand Prix mode there is also Time Trial mode where you can try to set up record times on your favorite tracks, as well as Vs Race where you can play with your own rules. You can customize speed class, CPU difficulty, which items appear, and more.' FROM games WHERE igdb_id = 250048 ON CONFLICT (game_id, language_code) DO NOTHING;
