INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destruction Darius', 'You play as Darius, a man with far too much spare time, an unlimited amount of mines and not a lot going on inside his head. To reach the top of the online scoreboards you must be fast, but also destructive. Every level can be played with two different rulesets and has two separate scoreboards. One favours speed, the other destruction.' FROM games WHERE igdb_id = 121430 ON CONFLICT (game_id, language_code) DO NOTHING;
