INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero Generations', 'In Hero Generations, each step you take is an entire year of your hero''s life. You explore a procedurally generated world in search of fame and a mate to have a child with before you die. After your life ends, you take control of your child in the world you left behind, in the hope of continuing your family legacy. Each turn becomes a meaningful life decision: you can focus on building and crafting the world around you, or adventuring to far off lands to make a bigger name for yourself.' FROM games WHERE igdb_id = 17301 ON CONFLICT (game_id, language_code) DO NOTHING;
