INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Emptiness', 'Change the perspective of your own psyche. In this game you choose the course of your gameplay and can solve mini-games in many ways! Your experience may be something satanic-like or sweet, innocent and happy. The Emptiness is a tough game and recommended to someone looking for a challenge, who doesn’t mind searching for very well hidden items. Ultimately, The Emptiness offers genuine difficulty, plus a captivating fright factor.' FROM games WHERE igdb_id = 139431 ON CONFLICT (game_id, language_code) DO NOTHING;
