INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steamalot: Epoch''s Journey', 'Steamalot is a medieval steampunk tactical card game. As a player you build a deck of characters, skills, and equipment. During a game players play characters onto a battlefield. Then those characters maneuver around the field in turn based combat. The objective is to eliminate all of the opponent''s characters from the board (or in some cases just their commander card). Cards can be gained and leveled between games.' FROM games WHERE igdb_id = 35435 ON CONFLICT (game_id, language_code) DO NOTHING;
