INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spies in the Night', 'Well, hello there!! My name is Starling, Ray Starling. I love sounding all James-Bondy. I''m here to tell you a little secret. I have an odd job, by odd job I mean I kill people and blow things up. Now killing people for money is frowned upon and anyone with any common sense would turn their backs on it. For me, this job, THIS JOB, is my crowning moment. How many people can say that the President of the United States hand-picked YOU for your unique resume.
