INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PixelJunk Nom Nom Galaxy', 'Welcome to Soup Co., Astroworker! As an integral part of the Soup Co. family, your mission is to explore the remote planets in search of tasty ingredients to make the galaxies most delicious soups and then rocket them into the gullets of our hungry customers. But this isn''t your typical soup kitchen - Astroworkers must battle against the planet''s elements, alien plants and animals, and dastardly rival soup corporations! Build your base of operations with the help of your fellow Astroworkers and handy Soup Co. robots, make the galaxies most mouth-watering soups, then defend yourself from local wildlife and our rivals.
