INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors 4: Empires', 'Sengoku Musou 4: Empires is the third Samurai Warriors Empires title. The gameplay will focus more on strategy as in other Empires expansions, with players issuing commands and taking suggestions to and from their subordinate military officers. Samurai Warriors 4-II serves as the game''s base for featured characters, action, and visuals. The overall concept is to present "the ultimate Warriors conquest simulator". In a response to fan feedback, this game will reuse qualities from the first Empires title. Developers from the Nobunaga''s Ambition series have worked on the simulation parts of this game. No new playable characters are appearing, but the number of character events are heightened throughout the game.' FROM games WHERE igdb_id = 12280 ON CONFLICT (game_id, language_code) DO NOTHING;
