INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danganronpa: Unlimited Battle', 'Danganronpa: Unlimited Battle is an action game in the Danganronpa series. Contrary to Danganronpa: Trigger Happy Havoc and Danganronpa 2: Goodbye Despair, which were visual novels, Danganronpa: Unlimited Battle is a co-op action video game. The player must assemble a team of four characters, and use the touch screen to slingshot attacks against the opposing side of enemies, similar to the game Monster Strike, and pinball. The game may be controlled by one to four players. The game is be free-to-play and has in-app purchases, which allows the player to buy the in-game currency from prior titles called "Monokuma Coins".' FROM games WHERE igdb_id = 11745 ON CONFLICT (game_id, language_code) DO NOTHING;
