INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chibi-Robo! Zip Lash', 'Chibi-Robo! Zip Lash comes to the Nintendo 3DS system with a fresh, new take on the franchise. In this side-scrolling game, Chibi-Robo uses his plug and cord to whip enemies, grapple onto ledges, and swing across chasms. Power-up the plug and cord to search for collectables and explore previously out of reach areas.' FROM games WHERE igdb_id = 11216 ON CONFLICT (game_id, language_code) DO NOTHING;
