INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utawarerumono: Mask of Deception', 'Utawarerumono: Mask of Deception is a grand tale that will enchant the hearts and minds of players as it takes them on an incredible journey. With a beautiful visual novel story experience, intriguing characters, fast-paced SRPG combat, world-class soundtrack and more. The game begins atop a snowy mountain where the protagonist awakens in an unfamiliar wilderness, surrounded by deadly creatures, with nothing but a hospital gown and a splitting headache. However, he''s rescued by a beautiful girl named Kuon, who sports both adorable animal ears and a beastlike tail. Finding that the hapless man has no memory of anything, Kuon decides to take the amnesiac into her care, naming him Haku.' FROM games WHERE igdb_id = 13548 ON CONFLICT (game_id, language_code) DO NOTHING;
