INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stranded Deep', 'Stranded Deep will feature a unique physically-based crafting and building system. Great care has been taken to minimize, even eliminate, most of the in-game UI. You will be able to craft a variety of crude weapons and tools such as spears, axes, knives, bows and even crossbows. And then there’s an assortment of everyday items to figure out how to craft. You will also be able to build a diverse range of unique shelters and rafts.' FROM games WHERE igdb_id = 8751 ON CONFLICT (game_id, language_code) DO NOTHING;
