INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mathland', 146687, '2015-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ake.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcdl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MathLand', 'An evil pirate, Max, has stolen the sacred gems and has cursed the islands filling them with obstacles and traps. Help Ray, our pirate, find the gems and restore the natural order of things. Navigate your ship through the seas to get them, but remember: you will need a spyglass to discover new islands. Solve fun math games to get them: addition, subtraction, numbering, multiplication tables, and division. The islanders need you! EVERY ISLAND IS AN ADVENTURE Have fun with over 25 levels and negotiate all kinds of obstacles in order to get to the chest that holds the gem. It will be a real adventure—you''ll have to deal with quicksand, bewitched parrots, volcanoes with lava, puzzle games, magic doors, funny carnivorous plants, etc. It will surprise you! EDUCATIONAL CONTENT For children aged 5-6: * Learning to add and subtract with very small numbers and amounts (1 to 10). * Sorting numbers from higher to lower (1 to 10) and vice versa * Reinforcing mental arithmetic with already learned additions and subtractions. For children aged 7-8: * Learning to add and subtract with larger numbers and amounts (1 to 20). * Getting started on learning multiplication tables. * Sorting numbers from higher to lower (1 to 50) and vice versa * Developing mental arithmetic with educational games based on addition, subtraction, and multiplication tables. For children aged 9+ and adults: * More complex additions and subtractions, teaching mental association of numbers with different arithmetic strategies (adding and subtracting). * Reinforcing the learning of all multiplication tables.…' FROM games WHERE igdb_id = 146687 ON CONFLICT (game_id, language_code) DO NOTHING;
