INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paranoia 2: Savior', 'Paranoia 2: Savior is the standalone sequel to the Half-Life mod Paranoia, which was ported to the Xash3D engine as Paranoia: The Game. Paranoia 2: Savior takes place shortly after the first game, putting the player back in the shoes of Major Alexander Kalashnikov as he continues his descent into the abandoned KROT-1 laboratory. The deeper Alex descends, the more he learns about the experiments that took place there, discovering that the monsters within must be eradicated at any cost.
