INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corpse Party', 'Corpse Party (known as Corpse Party BloodCovered: ...Repeated Fear in Japan) is a survival horror adventure game in the Corpse Party series created by Team GrisGris. The game is a remake of the PC game Corpse Party BloodCovered, which in turn was a remake of the original Corpse Party game released in 1996. Several changes were made from the PC version, such as enhanced background graphics, inclusion of CG event artwork, and professional voice actors.
