INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard West', 'Welcome to the Wild West like you’ve never seen it before. When a tragic turn of events sets one man down a path of supernatural chaos and revenge, he must brutally hunts down all those whom wronged him. Follow Warren on his descent into the darkest recesses of the human soul, and try to survive in a word full of hard choices and even harder consequences. Because in this world, death is a constant presence and the black pacts which you make with forces beyond human comprehension will forever haunt all those around you.
