INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SteamWorld Heist', 'Join Captain Piper Faraday, smuggler and occasional pirate, as she recruits a rag-tag team of steam-driven robots and sets out on a daring adventure. With your hearty crew you’ll board, loot and shoot your way through enemy spaceships. Overcome the challenges of the vast frontier by upgrading your robots with unique abilities, weapons – and even stylish hats!' FROM games WHERE igdb_id = 15167 ON CONFLICT (game_id, language_code) DO NOTHING;
